(window.GIM_TS=window.GIM_TS||{})["Nazir.2"]={"from":48,"a":[["\u0003שהפרישו\u0004 תחילה \u0003מעות לקיניהם\u0004 ואחר כך העשירו, אם \u0003רצה\u0004 בעל המעות לשנות אותן ו\u0003להביא בהן חטאת בהמה —\u0004 \u0003יביא,\u0004 רצה להביא בהם \u0003עולת בהמה —\u0004 \u0003יביא\u0004 וישלים את מחיר הבהמות ממעות אחרות. \u0003מת\u0004 המפריש \u0003והיו לו מעות סתומין —\u0004 \u0003יפלו\u0004 הכל \u0003לנדבה\u0004 ואף דמי חטאת שבהן. ומכאן שלא רק בנזיר קיים אותו דין שמעות סתומים יפלו לנדבה!","ומשיבים: \u0003תנא\u0004 \u0005[שנה\u0006\u0005]\u0006 \u0003נזיר ו\u0004גם \u0003חייבי קינין דדמו ליה\u0004 \u0005[שדומים לו\u0006\u0005]\u0006 ונחשבים לענין אחד, \u0003ולאפוקי מהא דתניא\u0004 \u0005[ולהוציא מ\u0006מקרה זה ששנינו בברייתא\u0005]:\u0006 \u0003מי שהיה מחוייב חטאת\u0004 על חטא שחטא, \u0003ואמר\u0004 נוסף לכך בנדבה: \u0003\"הרי עלי עולה\", והפריש מעות ואמר \"הרי אלו לחובתי\",\u0004 שאינו ברור אם נתכוון לחובת החטאת או לחובת נדר העולה, מה עושים באותן מעות?","אם \u0003רצה להביא בהן חטאת בהמה —\u0004 \u0003לא יביא.\u0004 רצה להביא בהן \u0003עולת בהמה —\u0004 \u0003לא יביא. מת והיו לו מעות סתומים —\u0004 \u0003ילכו לים המלח.\u0004 שבמקרה כזה, בו אין שני הקרבנות באים כחובה לשם אותו ענין, לא ניתן להשתמש במעות הסתומים לשם נדבה.","\u0003אמר רב אשי: הא\u0004 \u0005[זה\u0006\u0005]\u0006 ש\u0003אמרת\u0004 בענין נזיר שאם היו לו דמים \u0003מפורשין לא\u0004 יביא מכולם נדבה, אלא דמי חטאת ילכו לים המלח וכו' — \u0003לא תימא\u0004 \u0005[אל תאמר\u0006\u0005]\u0006 שהוא רק במקרה ש\u0003אמר\u0004 ופירש \u0003\"אלו לחטאתי, ואלו לעולתי, ואלו לשלמי\",\u0004 כל אחד לעצמו. \u0003אלא אפילו אמר \"אלו לחטאתי ולעולתי ולשלמי\"\u0004 אף שלא חילק את המעות לכל אחד ואחד מקורבנותיו — \u0003מפורשין הן\u0004 נחשבים לענין זה, ואינם נידונים כמעות סתומות.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים\u0006\u0005]\u0006 לשון אחרת, \u0003אמר רב אשי: לא תימא\u0004 \u0005[אל תאמר\u0006\u0005]\u0006 שאין הם נקראים מפורשים \u0003עד דאמר\u0004 \u0005[שיאמר\u0006\u0005]\u0006 \u0003\"אלו לחטאתי ולעולתי ולשלמי\", אלא אפילו אמר\u0004 בלשון כללית יותר: \u0003\"אלו לחובתי\" —\u0004 \u0003הרי הן כמפורשין.\u0004","\u0003אמר רבא: הא דאמרן\u0004 \u0005[זו שאמרנו\u0006\u0005]\u0006 ש\u0003מעות סתומין יפלו\u0004 כולם \u0003לנדבה\u0004 הרי זה דווקא במקרה שדמי כל הקרבנות מעורבים, אבל \u0003אם נפלה דמי חטאת מביניהן,\u0004 שחלק מסכום זה היה מובדל לשם דמי חטאת — \u0003הרי\u0004 השאר \u0003הן\u0004 מעתה \u0003כמפורשין,\u0004 ולא כולם יפלו לנדבה, כלומר, לעולה, אלא הסכום הראוי לעולה — לעולה, והראוי לשלמים — ילך לשלמים (ונאכלים ליום אחד ואינם טעונים לחם)."],["\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא כשיטתו\u0005]\u0006 של \u0003רבא:\u0004 אמר \u0003\"\u0004מעות \u0003אלו לחטאתי והשאר לשאר נזירותי\"\u0004 ומת, \u0003דמי חטאת —\u0004 \u0003ילכו לים המלח, והשאר —\u0004 \u0003יביא חציו לעולה וחציו לשלמים. ומועלין בכולן,\u0004 שאם השתמש בשאר הכסף כולו — הריהו חייב קרבן מעילה משום דמי העולה המעורבים בהם, \u0003ו\u0004אולם \u0003אין מועלין\u0004 אם השתמש \u0003במקצתן,\u0004 שמא אותו הכסף שהוציא כסף של שלמים הוא, ואין מועלים בהם.","אם אמר \u0003\"\u0004מעות \u0003אלו לעולתי והשאר לשאר נזירותי\" —\u0004 \u0003דמי עולה יביאו\u0004 בהם \u0003עולה, ומועלין בהן. והשאר יפלו לנדבה\u0004 מאחר ודמי חטאת מעורבים בהם, \u0003ומועלין,\u0004 כלומר, חייבים קרבן מעילה אם השתמשו \u0003בכולן\u0004 משום דמי החטאת המעורבים בהם, \u0003ואין מועלין\u0004 אם השתמשו רק \u0003במקצתן,\u0004 שמא אותו הכסף שהשתמשו בו של שלמים היו, ואין בהם מעילה.","\u0003אמר רב הונא אמר רב: לא שנו\u0004 חילוק זה בנזיר בין מעות סתומים ומפורשים \u0003אלא\u0004 ב\u0003מעות\u0004 שנועדו לקרבנות, \u0003אבל\u0004 אם הפריש \u0003בהמה\u0004 מסויימת לקרבנו — \u0003הרי היא כמפורשת,\u0004 משום ששלושת קרבנות הנזיר שונים זה מזה, לחטאת — מביא נקבה, לעולה — זכר, ולשלמים איל בן שנתיים, ומובן מאליו מה מופרש לצורך מה, ולכן אם מתו הבעלים יהא דינו של כל קרבן כראוי לו: חטאת — תמות, כדין כל חטאת שמתו בעליה, עולה — תקרב עולה, ושלמים — יקרבו שלמים וייאכלו ליום אחד, ואינם טעונים לחם.","\u0003אמר רב נחמן: הא דאמרי\u0004 \u0005[זו שאומרים\u0006\u0005]\u0006 שאם הפריש \u0003בהמה הרי היא כמפורשת —\u0004 \u0003לא שנו אלא\u0004 דווקא כשהיא בהמה \u0003תמימה,\u0004 שאותה עצמה יש להקריב, \u0003אבל\u0004 אם הפריש בהמה \u0003בעלת מום,\u0004 אפילו הפריש שלוש בהמות, נקבה, זכר, ואיל בן שנתיים, והן בעלות מום — \u0003הרי היא,\u0004 כל אחת מהן, נחשבת \u0003כסתומה,\u0004 שהרי אינו מקריב בהמה זו עצמה אלא מוכרה ומשתמש בדמיה, ודמים אלו לא נתפרשו. \u0003אבל נסכא\u0004 \u0005[חתיכת כסף\u0006\u0005] —\u0006 \u0003לא,\u0004 שאם הפריש חתיכות כסף, הרי אלו נחשבות כמפורשות, שהרי כל אחת ניכרת לעצמה, וכל אחת מהן לצורך קרבן מסויים.","\u0003ורב נחמן בר יצחק אמר: אפילו נסכא\u0004 \u0005[חתיכת כסף\u0006\u0005]\u0006 נחשבת כמעות סתומות, \u0003אבל סואר\u0004 \u0005[צבר\u0006\u0005]\u0006 \u0003של קורות —\u0004 \u0003לא,\u0004 שאם הפריש שלושה צברים של קורות בנין לצורך קרבנותיו נחשב הדבר כמו מעות מפורשות. \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב שימי בר אשי לרב פפא: מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים\u0006\u0005]\u0006 רב, רב נחמן ורב נחמן בר יצחק — האם משום \u0003דאמרי\u0004 \u0005[ש\u0006הם אומרים\u0005]:\u0006 \u0003מעות ולא בהמה, ולא נסכא, מעות ולא סוורא,\u0004 שהם סבורים שרק בענין מעות קיבלו במסורת דין סתומים, ואין לדמות לכך כל דבר אחר? \u0003אלא מעתה\u0004 לפי זה צריך לומר גם \u0003מעות ולא עופות!\u0004","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך גם כן\u0006\u0005]\u0006 הוא הדין, ועופות אינם נחשבים כסתומים, \u0003אלא הא\u0004 \u0005[זו\u0006\u0005]\u0006 ש\u0003אמר רב חסדא: אין הקינין\u0004 (זוג עופות, תורים או בני יונה, שמביאים אחד מהם לעולה ואחד לחטאת) \u0003מתפרשות\u0004 (נבדלות, מוגדרות) \u0003אלא אי\u0004 \u0005[אם,\u0006 או\u0005]\u0006 \u0003בלקיחת בעלים,\u0004 כאשר הבעלים קונים ומחליטים בשעת הקניה לייחד כל אחד לקרבן מסויים, \u0003אי\u0004 \u0005[אם,\u0006 או\u0005]\u0006 \u0003בעשיית כהן\u0004 שהכהן בזמן ההקרבה מחליט איזה לעולה ואיזה לחטאת. ומכאן מובן שהלוקח זוג עופות סתם — דינם כסתומים, ולכן יכול הכהן להחליט למה הוא מייעד כל אחד.","יש לשאול לפי דבריך: \u0003אמאי\u0004 \u0005[ומדוע\u0006\u0005]?\u0006 \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 דווקא ב\u0003מעות גמירין לה\u0004 \u0005[למודים\u0006 אנו דבר זה\u0005]\u0006 ולא בדברים אחרים! ומדברי רב חסדא משמע שגם בעופות יש דין של סתומים, ואם כן אף בהמה, נסכא וסואר של קורות דינם כן!"],["\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 רב פפא: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מקשה מכאן, ומגיע למסקנה שכל דבר הוא בכלל מעות סתומים, \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]\u0006 \u0003רבן שמעון בן גמליאל אומר: הביא שלש בהמות\u0004 שונות לנזירותו, \u0003ולא פירש\u0004 בכל אחת לאיזה קרבן היא, \u0003הראויה לחטאת\u0004 (כבשה) — \u0003תקרב חטאת,\u0004 הראויה \u0003לעולה\u0004 (זכר של צאן או בקר) — \u0003תקרב עולה, לשלמים\u0004 (זכר או נקבה אחרים) — \u0003תקרב שלמים.\u0004 ולשיטתך, שלא רק למעות יש דין סתומים, \u0003אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 יהא כן? \u0003הא אמרת\u0004 \u0005[הרי אתה אומר\u0006\u0005]\u0006 כי \u0003בהמה לאו\u0004 \u0005[לא\u0006\u0005]\u0006 \u0003כמפורשת דמי\u0004 \u0005[נחשבת\u0006\u0005]\u0006 אלא כמעות סתומים, וכיצד אנו מחליטים מה הבהמה!","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 רב שימי בר אשי: \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 לגבי עופות יש כתוב המלמדנו דבר זה, כאמור \u0003\"ולקח...\u0004 והיה האחד חטאת והאחד עולה\u0003\"\u0004 (ויקרא יד, כא-כב) האמור בבעלים המפרישים את הקרבן, ואחר כך נאמר בכהן \u0003\"ועשה\u0004 את האחד מן התורים... את האחד חטאת ואת האחד עולה\" (ויקרא יד, ל-לא).","כך \u0003אמר רחמנא\u0004 \u0005[אמרה תורה\u0006\u0005],\u0006 ומכאן שההפרשה וההגדרה לקרבן הן נעשות \u0003אי\u0004 \u0005[אם,\u0006 או\u0005]\u0006 \u0003בלקיחת\u0004 (בקניית) \u0003בעלים\u0004 שבשעת קניית העופות הוא מחליט לאיזה קרבן הוא מפריש אותם, \u0003אי\u0004 \u0005[אם,\u0006 או\u0005]\u0006 \u0003בעשיית כהן.\u0004 ומשום כך יכול אני ללמוד גם לגבי דברים אחרים, כגון בעלת מום ונסכא, שיהא דינם כמעות סתומים. ואילו הקושיה שהקשית מדברי רבן שמעון בן גמליאל אינה קושיה, לפי שהוא מקרה מיוחד. שהרי \u0003הכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005]\u0006 כאשר הפריש בהמות מסויימות אלה לקרבנות נזירותו"],["\u0003מי מצית אמרת\u0004 \u0005[האם יכול אתה לומר\u0006\u0005]\u0006 \u0003הדין\u0004 \u0005[זו\u0006\u0005]\u0006 של \u0003חטאת תקרב עולה?\u0004 הרי \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 בחטאת, קריבה רק \u0003נקבה,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 בעולה קרב רק \u0003זכר,\u0004 והרי זה כאילו פירש למה מיועד כל קרבן. ואם כן, אינך יכול להשוות דבר זה לשאר דברים שאינם מפורשים מצד עצמם, כגון בהמה בעלת מום ונסכא, שדינם כסתומים.","\u0003מתיב\u0004 \u0005[מקשה\u0006\u0005]\u0006 \u0003רב המנונא\u0004 על דברי רב נחמן, בראשית הסוגיא: \u0003ומי אמרינן\u0004 \u0005[והאם אומרים אנו\u0006\u0005]\u0006 ש\u0003בהמה בעלת מום כסתומה דמיא\u0004 \u0005[\u0006היא נחשבת\u0005]?\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 ראיה שלא כדבריך ממה ששנינו: \u0003כיצד\u0004 (באיזה אופן) \u0003אמרו האיש מגלח\u0004 (מביא קרבנות של תגלחת נזיר) \u0003על נזירות אביו?\u0004 ובהמשך הדברים נאמר: אבל \u0003בזמן שהיה הוא ואביו נזירים, והפריש אביו מעות ל\u0004קרבנות \u0003נזירותו ומת, ואמר\u0004 הבן \u0003\"הריני נזיר על מנת שאגלח\u0004 (אביא קרבנות) \u0003על מעות\u0004 שהפריש \u0003אבא\",\u0004 במקרה זה אינו מגלח על נזירות אביו.","ולכן, אם \u0003היו לו\u0004 לאב \u0003מעות סתומות —\u0004 \u0003יפלו\u0004 אותם מעות \u0003לנדבה.\u0004 ואם \u0003היתה לו בהמה מופרשת; חטאת —\u0004 \u0003תמות,\u0004 כדין כל חטאת שמתו בעליה, \u0003עולה —\u0004 \u0003תקרב עולה, ושלמים יקרבו שלמים. מאי לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 מדובר שהיתה בהמה זו \u0003אפילו בעלת מום?\u0004 שהרי לא חילקה הברייתא אלא בין מעות לבהמה. ואם כן רואים שאף בעלת מום נחשבת כמפורשת, שלא כדברי רב נחמן!","ודוחים: \u0003לא,\u0004 מדובר כאן דווקא בבהמה \u0003תמימה\u0004 (שאינה בעלת מום), שהיא עצמה ראויה לקרבן, ולכן נחשבת כמפורשת. ועל כך מקשים: \u0003אבל\u0004 לפי זה אם היתה זו בהמה \u0003בעלת מום,\u0004 האם \u0003כסתומה דמיא\u0004 \u0005[\u0006היא נחשבת\u0005]?\u0006 אם כן \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 נשנתה חלוקה בין בהמה ל\u0003מעות\u0004 סתומים? \u0003לימא\u0004 \u0005[יאמר\u0006\u0005]\u0006 כך: \u0003היתה לו בהמה בעלת מום —\u0004 \u0003יפלו\u0004 דמיה \u0003לנדבה,\u0004 ותהיה חלוקה זו בבהמות עצמן, וממנה נלמד לגבי מעות סתומים!","ומשיבים: \u0003הכי נמי\u0004 \u0005[כך גם כן\u0006\u0005]\u0006 הכוונה, ואין הבדל בין בעלת מום ומעות, שהרי \u0003בעלת מום למאי קדישא\u0004 \u0005[למה\u0006 היא קדושה\u0005] —\u0006 \u0003לדמי\u0004 \u0005[לדמים\u0006\u0005]\u0006 שיקבלו עבורה, ו\u0003דמי היינו\u0004 \u0005[דמים — הם\u0006\u0005]\u0006 \u0003מעות.\u0004 ונמצא שאין לדחות ממשנה זאת את דברי ר' נחמן שדין בעלת מום אינה כמעות סתומים.","\u0003מתיב\u0004 \u0005[מקשה\u0006\u0005]\u0006 \u0003רבא\u0004 גם כן על דברי רב נחמן ממה ששנינו בקשר לקרבן חטאת: נאמר בתורה \u0003\"\u0004והביא את \u0003קרבנו\"\u0004 (ויקרא ד, כג), וההדגשה היא: \u0003בקרבנו\u0004 שלו \u0003הוא יוצא\u0004 ידי חובתו, \u0003ואינו יוצא בקרבן אביו\u0004 אם אביו נתחייב בקרבן חטאת, והפרישו, ומת. \u0003יכול לא יצא בקרבנו של אביו שהפריש\u0004 דווקא כשאין העבירות של האב והבן שוות בחומרתן, כגון \u0003מן\u0004 עבירה \u0003הקלה\u0004 שחטא האב \u0003על\u0004 עבירה \u0003החמורה\u0004 שחטא בה הבן, \u0003או מן החמורה\u0004 שחטא האב \u0003על הקלה\u0004 שחטא הבן,","\u0003אבל יוצא בקרבן שהפריש אביו מן הקלה על הקלה או מן החמורה על החמורה —\u0004 \u0003תלמוד לומר: \"קרבנו\",\u0004 ושוב \u0003\"קרבנו\"\u0004 (ויקרא ד, כח), פעם נוספת, להדגיש: \u0003בקרבנו\u0004 שלו \u0003הוא יוצא ואינו יוצא\u0004 בכל מקרה \u0003בקרבנו של אביו.\u0004","ומכל מקום יש לשאול: \u0003יכול לא יצא בקרבן אביו בבהמה שהפריש, אפילו מן הקלה על הקלה,\u0004 וכן \u0003מן החמורה על החמורה\u0004 כפי שלמדנו, \u0003שהרי אין אדם מגלח על בהמת אביו בנזירות,\u0004 ומוכח שאין בכך דין ירושה, \u0003אבל\u0004 נאמר כי \u0003יוצא\u0004 הבן ידי חובתו \u0003במעות שהפריש אביו\u0004 לקרבנו, \u0003אפילו מן החמורה על הקלה, או מן הקלה על החמורה, שהרי אדם מגלח על מעות\u0004 שהפריש \u0003אביו בנזירות,\u0004"],["\u0003בזמן שהן סתומין ולא בזמן שהן מפורשין,\u0004 ואם כן הוא הדין למי שאביו הפריש מעות לחטאת סתם, שיצא בהם לשם חטאו — \u0003תלמוד לומר: \"קרבנו\"\u0004 (ויקרא ד, לב) להדגיש: \u0003בקרבנו הוא יוצא, ואינו יוצא\u0004 אף \u0003ב\u0004מעות שהופרשו לצורך \u0003קרבן אביו.\u0004","וממשיכים עוד לברר: \u0003יכול לא יצא במעות שהפריש\u0004 אביו \u0003אפילו\u0004 כאשר שוות בחומרתן העבירות של האב והבן, כגון \u0003מן הקלה על הקלה\u0004 או \u0003מן החמורה על החמורה, אבל יוצא\u0004 הוא \u0003בקרבן שהפריש לעצמו מן הקלה על החמורה, מן החמורה על הקלה —\u0004 \u0003תלמוד לומר: \"קרבנו... על חטאתו\"\u0004 (ויקרא ד, כח) לומר: \u0003עד שיהא קרבנו לשום\u0004 (לשם) \u0003חטאו\u0004 המסויים, ולא על חטא אחר.","\u0003יכול לא יצא בבהמה שהפריש לעצמו מן הקלה על הקלה או מן החמורה על החמורה,\u0004 או \u0003אפילו מן הקלה על החמורה או מן החמורה על הקלה,\u0004","\u0003שכן אם הפריש בהמה על החלב\u0004 שאכל בשגגה \u0003והביא\u0004 את החטאת הזו \u0003על הדם\u0004 שאכל בשגגה, \u0003או\u0004 הפריש \u0003על הדם והביא על החלב —\u0004 \u0003שהרי\u0004 במקרה זה דינו הוא ש\u0003לא מעל,\u0004 כיון שאין אפשרות לשנות בהמה זו מקדושתה לחולין, \u0003ו\u0004משום כך יש לומר שגם \u0003לא כיפר\u0004 במקרה שנשתנה קרבן זה לשם חטא אחר,","\u0003אבל יוצא במעות שהפריש לעצמו מן הקלה לקלה, ומן החמורה לחמורה, מן החמורה לקלה, ומן הקלה לחמורה,\u0004","\u0003שכן אם הפריש לעצמו מעות מן החלב\u0004 (כדי לקנות חטאת לכפר על אכילת חלב בשגגה) \u0003והביא\u0004 במעות אלה קרבן חטאת \u0003על הדם\u0004 שאכל בשגגה, או הפריש \u0003על הדם והביא על החלב —\u0004 \u0003שהרי מעל\u0004 במעות אלה אם השתמש בהם לצורך חולין, כיון שיש ביכולתו לשנות מקדושתם של המעות, \u0003ו\u0004משום כך נאמר שגם \u0003כיפר\u0004 אם נשתמש בהם לצורך קרבן על חטא אחר —","\u0003תלמוד לומר: \"על חטאתו\"\u0004 (ויקרא ד, לה) — \u0003עד שיהא קרבנו לשם חטאו,\u0004 ואינו רשאי להוציא מעות שהקדיש לשם חטאת אחת כדי לכפר על חטאת אחרת. עד כאן לשון הברייתא.","ושאלת רבא היא: לענייננו \u0003קתני מיהת\u0004 \u0005[שנה על כל פנים\u0006\u0005]\u0006 שם \u0003בהמה,\u0004 שאין אדם מגלח על בהמה שהפריש אביו לקרבן נזירות, \u0003מאי לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 נאמר הדבר \u0003אפילו\u0004 היתה הבהמה \u0003בעלת מום?\u0004 שהרי לא חילקו בדבר. ונמצא שדינה כמפורשת, ולא כדברי רב נחמן שדינה כמעות סתומים של אביו, שאדם מגלח עליהם. ודוחים: \u0003לא,\u0004 מדובר דווקא בבהמה \u0003תמימה\u0004 הראויה להקרבה, ורק היא נחשבת כמפורשת.","ושואלים: ולדבריך, \u0003אבל בעלת מום מאי\u0004 \u0005[מה\u0006\u0005]\u0006 יהא דינה — האם \u0003כסתומה דמיא\u0004 \u0005[\u0006היא נחשבת\u0005]?\u0006 אם כן \u0003מאי איריא דקתני\u0004 \u0005[מה שייך,\u0006 מדוע דווקא, ששנה\u0005]\u0006 בברייתא שאדם מגלח על \u0003מעות\u0004 סתומים \u0003שהפריש אביו? ליתני\u0004 \u0005[שישנה\u0006\u0005]\u0006 דין זה בבהמה \u0003בעלת מום\u0004 ומשם היינו למדים אף למעות! ומשיבים: \u0003הכי נמי\u0004 \u0005[כך הוא גם כן\u0006\u0005]\u0006 ואין הבדל בין הדברים, \u0003דלמאי חזיא\u0004 \u0005[ש\u0006הרי למה ראויה\u0005]\u0006 בהמה בעלת מום — \u0003לדמי\u0004 \u0005[לדמים\u0006\u0005],\u0006 \u0003דמי היינו\u0004 \u0005[דמים הם\u0006\u0005]\u0006 \u0003מעות.\u0004 ונמצא שאין מכאן ראיה נגד דברי רב נחמן, שבהמה בעלת מום הריהי כמעות סתומים.","בהמשך למשנה הקודמת, הדנה בהפרת בעל לאשתו לאחר שהפרישה קרבן נזירותה, דנה משנתנו בהפרת בעל נדר אשתו לאחר שסיימה את נזירותה והביאה את קרבנותיה למקדש. אם כבר \u0003נזרק\u0004 על המזבח \u0003עליה\u0004 (עבורה) \u0003אחד מן הדמים\u0004 של קרבנות נזירותה, הבעל \u0003אינו יכול\u0004 עוד \u0003להפר\u0004 את הנדר. \u0003ר' עקיבא אומר: אפילו\u0004 טרם זריקת הדם, אם כבר \u0003נשחטה עליה אחת מכל הבהמות\u0004 של קרבנותיה — שוב \u0003אינו יכול\u0004 עוד \u0003להפר.\u0004","ומוסיפה המשנה: \u0003במה דברים אמורים\u0004 שאינו יכול עוד להפר — כשהיתה מביאה את הקרבנות \u0003בתגלחת הטהרה\u0004 שבסוף נזירותה, \u0003אבל בתגלחת הטומאה\u0004 שלאחריה עליה לנהוג שוב נזירות כבתחילה — \u0003יפר\u0004 יכול הבעל להפר, מפני \u0003שהוא יכול לומר: אי אפשי\u0004 (אין רצוני) \u0003באשה מנוולת\u0004 שאינה שותה יין, ואם תנהג נזירות שלימה מחדש, הריהי נמצאת זמן ארוך בלא שתיית יין. \u0003ר' מאיר אומר: אף בתגלחת הטהרה יפר\u0004 לאחר שכבר החלה הקרבת הקרבנות, לפי \u0003שהוא יכול לומר: אי אפשי\u0004 (אין רצוני) \u0003באשה מגלחת,\u0004 והרי לאחר הקרבת הקרבנות צריכה הנזירה לגלח את שערה.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו\u0006\u0005]\u0006 לפיה משנזרק הדם שוב אין הבעל יכול להפר, שכן כבר נגמרה נזירותה, הריהי ש\u0003לא כ\u0004שיטת \u0003ר' אליעזר. דאי\u0004 \u0005[שאם\u0006 היא\u0005]\u0006 כשיטת \u0003ר' אליעזר —\u0004 \u0003האמר\u0004 \u0005[הרי אמר\u0006\u0005]:\u0006 \u0003תגלחת מעכבת,\u0004 שכל עוד הנזיר לא גילח את שערו הוא עדיין אסור בשתיית יין ובטומאת המת, \u0003וכיון\u0004 ש\u0003לא גילחה\u0004 עדיין — \u0003אסירה בחמרא\u0004 \u0005[אסורה ביין\u0006\u0005],\u0006 \u0003וכיון דאית\u0004 \u0005[שיש\u0006\u0005]\u0006 \u0003לה ניוול\u0004 בגלל אי שתיית יין \u0003מצי מיפר\u0004 \u0005[יכול להפר\u0006\u0005]\u0006 אפילו בתגלחת הטהרה לאחר זריקת הדם. ומסבירים את המשך המשנה: \u0003ובהא פליגי\u0004 \u0005[וב\u0006ענין זה חלוקים הם\u0005]\u0006 סתם משנה ור' עקיבא, שאינם סבורים כר' אליעזר;"],["\u0003תנא דידן סבר\u0004 \u0005[שלנו סבור\u0006\u0005]:\u0006 \u0003כיון דאיזדריק עלה\u0004 \u0005[שנזרק עליה\u0006\u0005]\u0006 \u0003דם, לאלתר שריא בחמרא\u0004 \u0005[מיד\u0006 היא מותרת ביין\u0005]\u0006 \u0003והא לית\u0004 \u0005[והרי אין\u0006\u0005]\u0006 \u0003לה ניוול,\u0004 ולפיכך מאותה שעה שוב אין הבעל יכול להפר, שהרי אין לו טענה להפרתו זו. \u0003ור' עקיבא סבר: אפילו\u0004 לא נזרק הדם, ואינה מותרת עדיין ביין, אם רק \u0003אישתחיטת\u0004 \u0005[נשחטה\u0006\u0005]\u0006 \u0003בהמה\u0004 לקרבנה שוב הבעל \u0003אינו יכול להפר —\u0004 \u0003משום הפסד קדשים,\u0004 שהרי אם יפר לה, אינה צריכה עוד קרבנות אלו, ואין נוהגים בהם עוד כבקרבנות כשרים, ואסור להפסיד קדשים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך\u0006\u0005]\u0006 \u0003ר' זירא: ואמאי\u0004 \u0005[ומדוע\u0006\u0005]\u0006 אומר אתה שיש בכך הפסד קדשים? יש פתרון לדבר: \u0003לזרוק\u0004 \u0005[יזרוק\u0006\u0005]\u0006 \u0003דמן שלא לשמן\u0004 של קרבנות נזיר, \u0003ויתיר\u0004 בכך את ה\u0003בשר באכילה\u0004 ולא ייפסלו הקדשים! \u0003מי\u0004 \u0005[האם\u0006\u0005]\u0006 \u0003לא תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כבשי עצרת\u0004 (שלמי ציבור שמביאים בחג השבועות) \u0003ששחטן שלא לשמן,\u0004 לשם עצרת, \u0003או ששחטן לפני זמנן\u0004 (בערב החג) \u0003או לאחר זמנן\u0004 (לאחר החג) — \u0003הדם יזרק\u0004 שלא לשמם (שהרי לשמם אינם ראויים) \u0003והבשר יאכל.\u0004","\u0003ואם היתה\u0004 זו \u0003שבת —\u0004 \u0003לא יזרק\u0004 הדם, לפי שאין הבשר נאכל בשבת, ונמצא עושה כעין מלאכה שלא לצורך שבת. \u0003ואם זרק\u0004 בכל זאת את הדם בשבת — \u0003הורצה\u0004 נתקבל קרבן זה, וצריך להמתין ו\u0003להקטיר אימורין\u0004 שלו \u0003לערב,\u0004 לשרוף את איבריו הפנימיים על גבי המזבח רק במוצאי שבת. ומכל מקום למדנו מכאן שזורקים לכתחילה דם קרבנות שונים שלא לשמם כדי להתיר את בשרם לאחר שחיטתם!","\u0003אמרי\u0004 \u0005[אומרים\u0006\u0005]:\u0006 \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 ש\u0003שחט\u0004 עבור האשה בקרבנות נזירותה \u0003עולה או שלמים\u0004 בלבד — \u0003הכי נמי\u0004 \u0005[כך גם כן\u0006\u0005]\u0006 ודאי יכול לעשות כן, לזרוק את דמם שלא לשמם, ולא יהיה בכך הפסד קדשים, ובמקרה כזה אכן סבור ר' עקיבא שעדיין יכול הבעל להפר. \u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים\u0006\u0005]\u0006 \u0003כגון ששחט חטאת ברישא\u0004 \u0005[בראש,\u0006 בתחילה\u0005]\u0006 וחטאת שנזרק דמה שלא לשמה — פסולה. ואם כן יש כאן הפסד קדשים אם יפר לה בעלה.","ומניין שאין סדר מחייב לשחיטת קרבנות הנזיר, ואפשר גם להקריב את קרבן החטאת תחילה — \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אם גילח על\u0004 (לאחר שהקריב) \u0003אחת משלשתן,\u0004 שלושת הקרבנות שנזיר חייב בהם: עולה, שלמים וחטאת — \u0003יצא.\u0004","שנינו במשנה: \u0003במה דברים אמורים\u0004 שאינו יכול להפר — \u0003בתגלחת טהרה, אבל בתגלחת טומאה —\u0004 \u0003יפר\u0004 הבעל אם ירצה, \u0003מפני שיכול לומר: אי אפשי\u0004 (אין רצוני) \u0003באשה מנוולת,\u0004 אשה שאינה יכולה לשתות יין. \u0003ור' מאיר אומר: אפילו בתגלחת טהרה יפר, מפני שיכול לומר: אי אפשי באשה מגלחת.\u0004","ומבררים את טענותיהם: \u0003ותנא קמא\u0004 \u0005[הראשון\u0006\u0005]\u0006 \u0003אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך\u0004 כנגד טענתו של ר' מאיר: \u0003אפשר בפאה נכרית\u0004 וכיון שלובשת האשה פאה נכרית אינה נראית מגולחת, ואין כאן ניוול בעיני הבעל, ואינו יכול להפר. \u0003ור' מאיר סבר\u0004 \u0005[סבור\u0006\u0005]:\u0006 \u0003בפאה נכרית, איידי דזוהמא\u0004 \u0005[מתוך ש\u0006היא מזוהמת\u0005]\u0006 \u0003לא ניחא ליה\u0004 \u0005[נוח לו\u0006\u0005]\u0006 ולכן רשאי להפר את נדרה.","\u0003האיש מדיר את בנו\u0004 הקטן \u0003בנזיר,\u0004 שיכול האב לגזור על בנו, אם עדיין לא הגיע לבגרות — שיהא נזיר, \u0003ואין האשה מדרת את בנה בנזיר.\u0004 ופרטי הדינים של נזירות זו, \u0003כיצד? גילח\u0004 הבן את שערו וגילה דעתו בכך שאינו חפץ בנזירות זו שהדירו אביו, \u0003או שגילחוהו קרוביו,\u0004 וכן אם \u0003מיחה\u0004 הבן ואמר שאינו רוצה בנזירות, \u0003או שמיחו קרוביו\u0004 — בטלה נזירותו.","ואם \u0003היתה לו בהמה מופרשת\u0004 לצורך קרבן נזירותו, הבהמה שהיתה מופרשת עבור \u0003החטאת —\u0004 \u0003תמות, והעולה\u0004 — \u0003תקרב עולה. ושלמים\u0004 — \u0003יקרבו שלמים, ונאכלין ליום אחד\u0004 כשלמי נזיר, ולא לשני ימים כשלמים רגילים, \u0003ואינן טעונין לחם,\u0004 חלות שבאות עם שלמי הנזיר.","\u0003היו לו מעות סתומין —\u0004 \u0003יפלו\u0004 כל המעות \u0003ל\u0004צורך \u0003נדבה\u0004 להקריב עולות ציבור על גבי המזבח. ואם היו \u0003מעות מופרשים\u0004 לצורך קרבנותיו, \u0003דמי חטאת —\u0004 \u0003ילכו לים המלח, לא נהנין\u0004 בהם לכתחילה \u0003ו\u0004אולם \u0003לא מועלין\u0004 בהם, שאם נהנה מהם אינו מביא קרבן מעילה. \u0003דמי עולה —\u0004 \u0003יביאו\u0004 מהם \u0003עולה\u0004 ואין נהנים מהם, \u0003ו\u0004אם נהנה מהם — \u0003מועלין בהן, דמי שלמים —\u0004 \u0003יביאו\u0004 מהם \u0003שלמים ונאכלין ליום אחד, ואינן טעונין לחם\u0004 כבשלמי נזיר.","שנינו במשנה שהאיש מדיר את בנו בנזיר, ועוד שנינו כי \u0003איש —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005]\u0006 מדיר, \u0003אבל אשה —\u0004 \u0003לא.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 הדבר? \u0003ר' יוחנן אמר: הלכה היא בנזיר,\u0004 כלומר, כך קיבלנו במסורת הלכה למשה מסיני. \u0003ור' יוסי בר' חנינא\u0004"],["\u0003אמר\u0004 בשם \u0003ריש לקיש: כדי לחנכו במצות\u0004 וללמדו כיצד נוהגים במצוות נזירות. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך\u0006\u0005]\u0006 \u0003אפילו אשה נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 תוכל להדיר את בנה בנזיר כדי לחנכו במצוות! ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003איש חייב לחנך בנו במצות, ואין האשה חייבת לחנך את בנה.\u0004","ועוד מקשים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003לר' יוחנן\u0004 ש\u0003אמר\u0004 ש\u0003הלכה היא בנזיר —\u0004 \u0003אמטו להכי\u0004 \u0005[משום כך\u0006\u0005]\u0006 אפשר לדייק במשנתנו: \u0003בנו —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005]\u0006 יכול להדירו בנזיר, \u0003בתו —\u0004 \u0003לא,\u0004 שכך נאמרה הלכה ואין לחפש לה טעם. \u0003אלא לריש לקיש\u0004 שהטעם הוא משום חינוך, אם כן \u0003אפילו בתו\u0004 יוכל האב להדירה בנזירות, משום חינוך! ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003בנו —\u0004 \u0003חייב לחנכו, בתו —\u0004 \u0003אינו חייב לחנכה,\u0004 ולכן גם אינו יכול להדירה בנזירות.","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003ל\u0004דעת \u0003ר' יוחנן\u0004 ש\u0003אמר הלכה היא בנזיר —\u0004 \u0003אהכי\u0004 \u0005[משום כך\u0006\u0005]\u0006 אפשר לדייק במשנתנו: \u0003בנזירות —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 ואילו \u0003ב\u0004שאר \u0003נדרים —\u0004 \u0003לא,\u0004 שאינו יכול להדיר את בנו בנדר אחר. \u0003אלא לריש לקיש\u0004 שהוא משום חינוך — אם כן \u0003אפילו נדרים\u0004 שיש בהם משום חינוך \u0003נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 יוכל להדיר את בנו!","ומשיבים: לשיטתו בלשון \u0003לא מיבעיא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 \u0003קאמר\u0004 \u0005[אמר\u0006\u0005]\u0006 התנא במשנתנו, וכך יש להבין: \u0003לא מיבעיא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 לומר \u0003בנדרים\u0004 אחרים של מצוה \u0003דלית ליה\u0004 \u0005[שאין לו\u0006\u0005]\u0006 לבן \u0003ניוול\u0004 כשמקיים את הנדר כשהדירו אביו, שוודאי יכול האב להדיר את בנו, \u0003אלא אפילו בנזירות דאית ליה\u0004 \u0005[שיש לו\u0006\u0005]\u0006 לבן \u0003ניוול,\u0004 שאינו שותה יין ואינו מתגלח — \u0003אפילו הכי\u0004 \u0005[כך\u0006\u0005]\u0006 \u0003חייב לחנכו,\u0004 ומשום כך גם יכול להדירו.","ועוד מקשים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003לר' יוחנן\u0004 ש\u0003אמר\u0004 ש\u0003הלכה\u0004 למשה מסיני \u0003היא בנזיר —\u0004 \u0003היינו דקתני\u0004 \u0005[זהו ששנה\u0006\u0005]\u0006 שאם \u0003מיחה או שמיחוהו קרוביו\u0004 מתבטלת הנזירות, שכך היתה ההלכה שאין הנזירות אלא בהסכמת הקרובים, ואין לחפש טעם לדבר.","\u0003אלא ל\u0004שיטת \u0003ר' יוסי בר' חנינא\u0004 ש\u0003אמר\u0004 בשם \u0003ריש לקיש,\u0004 שלדבריו טעם הדבר שיכול להדיר את בנו בנזיר משום חינוך הוא, אם כן \u0003כל כמיניהון\u0004 \u0005[\u0006האם הכל בכוחם\u0005]\u0006 של \u0003קרובים דאמרין ליה\u0004 \u0005[שאומרים לו\u0006\u0005]\u0006 לאב: \u0003לא תיגמריה\u0004 \u0005[תלמדו\u0006\u0005]\u0006 \u0003מצות?!\u0004 ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003כל חינוך\u0004 ש\u0003לא חשיב\u0004 \u0005[חשוב\u0006\u0005]\u0006 כגון מצות נזירות שאינה חובה המוטלת על האדם, \u0003לא ניחא ליה\u0004 \u0005[נוח לו\u0006\u0005]\u0006 לבן להצטער בדבר זה, ומשום כך יכולים הוא או קרוביו למחות בדבר.","ועוד מקשים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003לר' יוחנן\u0004 ש\u0003אמר\u0004 ש\u0003הלכה\u0004 מפורשת למשה מסיני \u0003היא בנזיר —\u0004 \u0003משום הכי\u0004 \u0005[כך\u0006\u0005]\u0006 \u0003מגלח\u0004 הבן את כל שערו בתום נזירותו, \u0003ו\u0004אף שתוך כדי כך \u0003עביד\u0004 \u0005[עושה\u0006\u0005]\u0006 גם \u0003הקפה\u0004 של פאות הראש ועובר על מה שנאמר \"לא תקיפו פאת ראשכם\" (ויקרא יט, כז), שהרי התורה שאסרה דבר זה, היא אשר ציוותה על הנזיר לגלח את שערו.","\u0003אלא ל\u0004דעת \u0003ר' יוסי בר' חנינא\u0004 ש\u0003אמר\u0004 בשם \u0003ריש לקיש\u0004 שהטעם הוא \u0003כדי לחנכו במצות,\u0004 ואין זה אלא מדברי סופרים, \u0003הא קעביד\u0004 \u0005[הרי הוא עושה\u0006\u0005]\u0006 \u0003הקפה\u0004 ואיך יידחה איסור תורה משום חינוך שהוא מצוה שמדברי סופרים!","ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003הקפת כל הראש\u0004 אסורה רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005]\u0006 שלא נאסר מן התורה אלא כאשר חותך רק את פאות הראש. \u0003ו\u0004מצוות \u0003חינוך\u0004 גם הוא \u0003מדרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005],\u0006 \u0003ואתי\u0004 \u0005[ובאה\u0006\u0005]\u0006 מצות \u0003חינוך\u0004 שהיא \u0003דרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005]\u0006 \u0003ודחי\u0004 \u0005[ודוחה\u0006\u0005]\u0006 איסור \u0003הקפה\u0004 שאף הוא \u0003דרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005].\u0006","ועוד מקשים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003לר' יוחנן\u0004 ש\u0003אמר\u0004 ש\u0003הלכה היא בנזיר —\u0004 \u0003אהכי\u0004 \u0005[משום כך\u0006\u0005]\u0006 כש\u0003מגלח\u0004 בסוף נזירותו \u0003מייתי\u0004 \u0005[מביא\u0006\u0005]\u0006 \u0003קרבן,\u0004 שכך נאמרה ההלכה — שיהא נזיר קטן זה נחשב כנזיר גדול לכל דבר, וקרבנו כקרבן כל נזיר.","\u0003אלא לר' יוסי בר' חנינא אמר ריש לקיש,\u0004 שעושה זאת רק \u0003כדי לחנכו במצות\u0004 — נמצא שאין זה קרבן שציוותה תורה, ואם כן \u0003הא קא מייתי\u0004 \u0005[הרי הוא מביא\u0006\u0005]\u0006 \u0003חולין לעזרה!\u0004 ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003חולין בעזרה לאו דאורייתא\u0004 \u0005[לא\u0006 איסור מן התורה הוא\u0005]\u0006 אלא רק מדברי סופרים, ומשום חשיבות מצוות חינוך הבן אין חכמים מקפידים על איסור זה.","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003לר' יוחנן\u0004 ש\u0003אמר\u0004 ש\u0003הלכה היא בנזיר —\u0004 \u0003אהכי\u0004 \u0005[על כן\u0006\u0005]\u0006 \u0003כי\u0004 \u0005[כאשר\u0006\u0005]\u0006 הבן \u0003מיטמא מייתי\u0004 \u0005[מביא\u0006\u0005]\u0006 \u0003קרבן ציפרין\u0004 \u0005[ציפורים\u0006\u0005]\u0006 \u0003ואכיל\u0004 \u0005[ואוכל\u0006\u0005]\u0006 \u0003כהן\u0004 חטאת העוף שהומתה ב\u0003מליקה\u0004 ולא בשחיטה, ודבר זה מותר רק בקרבנות העוף שמצוותם בכך.","\u0003אלא לר' יוסי בר' חנינא\u0004 ש\u0003אמר\u0004 בשם \u0003ריש לקיש, הא קאכיל\u0004 \u0005[הרי אוכל\u0006\u0005]\u0006 הכהן \u0003נבילה!\u0004 שאם אין זה קרבן שמחוייב בו — נמצא שהוא אוכל עוף שהומת שלא באופן המכשירו לאכילה, ודינו כנבילה.","ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' יוסי בר' יהודה\u0004 האומר ש\u0003אין\u0004 מצות \u0003שחיטה לעוף מן התורה.\u0004 שמן התורה בכל דרך שבה ממיתים את העוף הוא כשר, אלא שחכמים תיקנו שישחטו גם את העוף. \u0003ו\u0004כן סבור הוא כי הבאת \u0003חולין בעזרה לאו דאורייתא\u0004 \u0005[לא\u0006 אסורה מן התורה\u0005]\u0006 ולפיכך משום מצות חינוך שהיא מדברי סופרים נדחים איסורים אלה, שאף הם אינם אלא מדברי סופרים.","ושואלים: \u0003וסבר\u0004 \u0005[ו\u0006האם סבור\u0005]\u0006 \u0003ר' יוסי הכי\u0004 \u0005[כך\u0006\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר: מנין לחטאת העוף שהיא באה על\u0004 (בגלל) \u0003הספק, שאינה נאכלת —\u0004 \u0003תלמוד לומר: \"והזב את זובו לזכר ולנקבה\"\u0004 (ויקרא טו, לג), \u0003מקיש\u0004 (משווה) הכתוב כאן \u0003נקבה לזכר, מה זכר מביא קרבן על הודאי\u0004 (חטא שיודע בוודאות שעשה אותו בשגגה) — \u0003אף נקבה מביאה קרבן על הודאי, ומה זכר מביא\u0004 אשם תלוי \u0003על הספק —\u0004 \u0003אף נקבה מביאה\u0004 קרבן \u0003על הספק.\u0004","\u0003ו\u0004עוד: \u0003מה זכר, מ\u0004אותו \u0003מין שהוא מביא על הודאי\u0004 שהוא חטאת בהמה \u0003מביא על הספק\u0004 גם כן מין בהמה — איל לאשם, \u0003אף נקבה —\u0004 \u0003ממין שהיא מביאה על הודאי\u0004 שהוא עוף לזיבתה או ללידתה \u0003מביאה\u0004 גם \u0003על הספק.\u0004 מעתה יש לשאול: \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 כך שיש היקש כזה בפסוק, נאמר גם: \u0003מה זכר מביא קרבן ונאכל\u0004 קרבנו — \u0003אף נקבה\u0004 שמביאה קרבן לידה מספק \u0003מביאה קרבן ונאכל!\u0004 על כך \u0003אמרת\u0004 (יש לומר):"],["\u0003לא,\u0004 אין אתה יכול לומר כך, שכן \u0003אם אמרת\u0004 כך \u0003בזכר שכן\u0004 יש בהבאת קרבנו מספק רק ספק \u0003איסור אחד,\u0004 שמא מביא חולין בעזרה, \u0003תאמר בנקבה —\u0004 \u0003ש\u0004ספק \u0003שני איסורין\u0004 יש בה. עד כאן לשון הברייתא.","ונברר: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003שני איסורין\u0004 אלה? \u0003לאו\u0004 \u0005[\u0006האם לא\u0005]\u0006 \u0003איסור נבילה\u0004 (של אכילת עוף שנמלק) \u0003ו\u0004הבאת \u0003חולין בעזרה?\u0004 הרי שר' יוסי בר' יהודה סבור שהבאת חולין לעזרה אסורה מן התורה! \u0003מתקיף לה\u0004 \u0005[מקשה על כך\u0006\u0005]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו\u0006\u0005]\u0006 של \u0003רב איקא: ודילמא מיחייב\u0004 \u0005[ושמא מתחייבת\u0006\u0005]\u0006 \u0003עליה\u0004 הנקבה על דבר זה, לא מדין תורה, אלא \u0003משום דמיתחזי כתרין איסורין\u0004 \u0005[שנראה כשני איסורים\u0006\u0005]\u0006 שמן התורה, אף שבאמת אין הם אלא \u0003מדרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005]!\u0006","ובאשר לעצם המחלוקת בענין טעם ההלכה במדיר את בנו בנזיר, אם מכוח הלכה למשה מסיני או מפני מצוות חינוך, מציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שדבר זה הוא כמחלוקת תנאים\u0005]\u0006 שכבר דנו ונחלקו בבעיה זו. ששנינו: \u0003עד מתי מדיר\u0004 האב \u0003את בנו בנזיר —\u0004 \u0003עד שיביא\u0004 הבן \u0003שתי שערות,\u0004 אלו \u0003דברי רבי. ר' יוסי בר' יהודה אומר: עד שיגיע לעונת נדרים,\u0004 שהיא כשנה קודם לכן, כאשר הבן מבין כבר בטיבם של נדרים, ואם נודר ונמצא שיודע מה משמעות הדברים — נדרו קיים.","\u0003מאי לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 \u0003תנאי\u0004 \u0005[\u0006מחלוקת תנאים\u0005]\u0006 \u0003היא;\u0004 ש\u0003רבי סבר\u0004 \u0005[סבור\u0006\u0005]:\u0006 \u0003הלכה\u0004 למשה מסיני \u0003היא בנזיר, ו\u0004משום כך \u0003אף על גב\u0004 \u0005[אף על פי\u0006\u0005]\u0006 ש\u0003הגיע\u0004 הבן \u0003לעונת נדרים\u0004 עוד קודם, והוא יכול להחליט מדעתו אם רצונו בנדר, מכל מקום כך היתה ההלכה כי \u0003מדיר ליה ואזיל\u0004 \u0005[מדיר אותו\u0006 האב והולך\u0005]\u0006 \u0003עד דמייתי\u0004 \u0005[שמביא\u0006\u0005]\u0006 \u0003שתי שערות,\u0004 שהן סימן בגרות, ואז יצא הבן מרשותו. \u0003ור' יוסי בר' יהודה דאמר\u0004 \u0005[שאומר\u0006\u0005]\u0006 שיכול להדירו רק \u0003עד שיגיע לעונת נדרים, סבר\u0004 \u0005[סבור\u0006\u0005]\u0006 שדין זה שהאב מדיר את בנו הוא \u0003כדי לחנכו במצות, וכיון דנפיק מרשותיה\u0004 \u0005[שיוצא מרשותו\u0006 של האב\u0005]\u0006 שהבן הלא יכול כבר לנדור בעצמו — \u0003תו\u0004 \u0005[שוב\u0006\u0005]\u0006 \u0003לא מיחייב\u0004 \u0005[מחוייב\u0006\u0005]\u0006 האב לחנכו?","ודוחים: \u0003אמרי\u0004 \u0005[אומרים\u0006\u0005]:\u0006 \u0003לא,\u0004 אין הדבר כן. אפשר לומר \u0003דכולי עלמא\u0004 \u0005[שדעת הכל\u0006\u0005]\u0006 רבי ור' יוסי בר' יהודה כדעת ר' יוחנן ש\u0003הלכה היא בנזיר, והכא\u0004 \u0005[וכאן\u0006\u0005]\u0006 \u0003ב\u0004ענין \u0003\"מופלא הסמוך לאיש\" קמיפלגי\u0004 \u0005[חלוקים הם\u0006\u0005],\u0006 שדנו בשאלה לגבי ילד ש\"מפליא\" (נודר) סמוך להיותו איש, כלומר סמוך לבגרותו, שמקובל בידינו שנדרו (אם מבין הוא את מהות הנדר) קיים. ונחלקו בדבר מקורה של ההלכה.","\u0003רבי סבר\u0004 \u0005[סבור\u0006\u0005]:\u0006 \u0003מופלא הסמוך לאיש דרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005]\u0006 הוא שיכול לנדור, \u0003ו\u0004משום כך \u0003אתיא דאורייתא דחיא דרבנן\u0004 \u0005[באה\u0006 הלכה מן התורה שהאב מדיר את בנו ודוחה את התקנה שמדברי סופרים\u0005]\u0006 שתיקנו שסמוך לבגרותו הוא נקרא כבר גדול ועצמאי לענין נדרים. \u0003ו\u0004אילו \u0003ר' יוסי בר' יהודה סבר\u0004 \u0005[סבור\u0006\u0005]:\u0006 \u0003מופלא הסמוך לאיש דאורייתא\u0004 \u0005[מן התורה\u0006\u0005]\u0006 הוא, שעומד ברשות עצמו לענין נדרים, ולכן אין ההלכה שאב מדיר את בנו הקטן חלה עליו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005]\u0006 להיפך: \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל\u0006\u0005]\u0006 האיש מדיר את בנו בנזיר מדברי סופרים, \u0003כדי לחנכו במצות, ו\u0004גם הדין ש\u0003מופלא הסמוך לאיש\u0004 לדעת הכל תקנה \u0003דרבנן\u0004 \u0005[שמדברי סופרים\u0006\u0005]\u0006 \u0003היא\u0004 שנדריו קיימים. וטעם המחלוקת בין התנאים הוא ש\u0003רבי סבר\u0004 \u0005[סבור\u0006\u0005]:\u0006 \u0003אתי\u0004 \u0005[באה\u0006\u0005]\u0006 מצות \u0003חינוך\u0004 שהיא \u0003דרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005]\u0006 \u0003ודחי\u0004 \u0005[ודוחה\u0006\u0005]\u0006 את דין \u0003מופלא הסמוך לאיש\u0004 שהוא גם כן \u0003דרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005].\u0006","\u0003ור' יוסי בר' יהודה דאמר\u0004 \u0005[שאומר\u0006\u0005]\u0006 שהאב יכול להדיר את בנו רק \u0003עד שיגיע לעונת נדרים, קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003לא אתי\u0004 \u0005[באה\u0006\u0005]\u0006 מצות \u0003חינוך דרבנן\u0004 \u0005[שמדברי סופרים\u0006\u0005]\u0006 \u0003ודחי\u0004 \u0005[ודוחה\u0006\u0005]\u0006 דין \u0003מופלא הסמוך לאיש.\u0004 ואם כן אין קשר הכרחי בין מחלוקת תנאים זו ובין מחלוקת ר' יוחנן וריש לקיש לגבי דין מדיר בנו בנזיר, האם מקורו בהלכה למשה מסיני, או במצות חינוך.","לגופה של המחלוקת לגבי הזמן שמדיר האב את בנו, מציעים: \u0003לימא הני תנאי כי הני תנאי\u0004 \u0005[האם נאמר שתנאים אלה\u0006 נחלקו במחלוקת של תנאים אלה\u0005]\u0006 המצויה במקור אחר, \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 \u0003מעשה בר' חנינא שהדירו אביו בנזיר\u0004 בעודו קטן, \u0003והביאו לפני רבן גמליאל. והיה רבן גמליאל בודקו לידע אם הביא\u0004 כבר \u0003שתי שערות\u0004 והנדר לא חל, \u0003אם לא הביא\u0004 והנדר חל.","\u0003ר' יוסי אומר\u0004 שהיה בודקו \u0003לידע אם הגיע לעונת נדרים אם לאו\u0004 \u0005[לא\u0006\u0005],\u0006 שלדעתו זהו הזמן הקובע. \u0003אמר לו\u0004 הילד: \u0003רבי, אל תצטער\u0004 (אל תטרח) \u0003לבודקני,\u0004 אלא \u0003אם קטן אני —\u0004 \u0003אהיה\u0004 נזיר \u0003בשביל\u0004 (בגלל, משום) מה שהדירני \u0003אבא, אם גדול אני —\u0004 \u0003אהיה בשביל עצמי. עמד רבן גמליאל ונשקו על ראשו, אמר: מובטח אני בזה\u0004 בילד הזה \u0003ש\u0004סופו להיות \u0003מורה הלכה בישראל. אמרו:\u0004 אכן, \u0003לא היו\u0004 אלא \u0003ימים מועטים\u0004 שעברו \u0003עד ש\u0004אכן \u0003הורה הוראה בישראל.\u0004","ומעתה נברר לעניינינו: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003לר' יוסי בר' יהודה\u0004 ש\u0003אמר\u0004 שהאב יכול להדיר את בנו בנזיר רק \u0003עד שיגיע לעונת נדרים —\u0004 \u0003היינו דקאמר\u0004 \u0005[זהו שאמר\u0006\u0005]\u0006 \u0003\"אם קטן אני, אהיה בשביל אבא\"\u0004 שכוונתו — אם קטן אני, שלא הגיע עדיין לעונת נדרים. \u0003אלא, ל\u0004דעת \u0003רבי דאמר\u0004 \u0005[שאומר\u0006\u0005]\u0006 שהאב מדיר את בנו בנזיר \u0003עד שיביא שתי שערות,\u0004 אף שכבר נחשב גדול לענין נדרים, מה שאמר \u0003\"ואם גדול אני אהיה בשביל עצמי\",\u0004 מדוע יש צורך בדבר?"],["\u0003הא ברשותיה דאבוה קאים\u0004 \u0005[הרי ברשותו של אביו עומד\u0006 הוא\u0005]\u0006 עדיין לענין קבלת נזירות, שהרי לא הביא עוד שתי שערות! \u0003אלא\u0004 יש לפרש \u0003דאמר\u0004 \u0005[שאומר\u0006\u0005]\u0006 כך: \u0003אהא בשביל אבא, אהא בשביל עצמי.\u0004 שלא תלה זאת בספק אם הוא גדול לענין נדרים אם לאו, אלא האם יצא מרשות אביו לענין נזירות, כלומר, שהביא כבר שתי שערות, אם לאו.","ומעתה לשיטת רבי, \u0003אי אייתי\u0004 \u0005[אם הביא\u0006\u0005]\u0006 \u0003שתי שערות מעיקרא\u0004 \u0005[מתחילה\u0006\u0005]\u0006 לפני שהזירו אביו — הריהו \u0003קאים\u0004 \u0005[עומד\u0006\u0005]\u0006 \u0003בנזירות דיליה\u0004 \u0005[שלו\u0006 עצמו\u0005]\u0006 \u0003ו\u0004אם \u0003לבסוף,\u0004 לאחר הנזירות, הביא שתי שערות — הריהו \u0003קאים\u0004 \u0005[עומד\u0006\u0005]\u0006 \u0003בנזירות דאבוה\u0004 \u0005[של אביו\u0006\u0005]\u0006 שהדירו. \u0003ו\u0004אולם \u0003אי אייתי במצעי מאי\u0004 \u0005[אם הביא\u0006 שתי שערות באמצע הנזירות מה\u0005]\u0006 יועיל הדבר?","\u0003הניחא\u0004 \u0005[זה נוח\u0006\u0005]\u0006 שאלה זו אינה קשה \u0003ל\u0004שיטת \u0003ר' יוסי בר' יהודה דאמר\u0004 \u0005[שאומר\u0006\u0005]:\u0006 \u0003עד שיגיע לעונת נדרים,\u0004 שיש להניח שאף אם הגיע לעונת נדרים באמצע הנזירות שהדירו אביו, לא בטלה אותה נזירות. ואם כן ישלים נזירות זו ויביא קרבנותיו.","\u0003אלא לרבי דאמר\u0004 \u0005[שאומר\u0006\u0005]:\u0006 \u0003עד שיביא שתי\u0004 \u0003שערות מאי איכא למימר\u0004 \u0005[מה יש לומר\u0006\u0005]\u0006 והרי אם הביא שתי שערות בתוך כדי נזירות אביו — שוב אין נזירות זו חלה עליו, ומה יהא דינו? \u0003אמרי\u0004 \u0005[אומרים\u0006\u0005]:\u0006 \u0003ל\u0004דעת \u0003רבי ליכא תקנתא\u0004 \u0005[אין תקנה\u0006\u0005]\u0006 לילד זה \u0003עד דיתיב דיליה ויתיב דאבוהי\u0004 \u0005[שישב\u0006 את זמן הנזירות שלו וישב גם בעבור נזירות שהזירו אביו\u0005],\u0006 כלומר, שישים יום.","\u0003האיש מגלח על\u0004 קרבנות שנועדו במקורם ל\u0003נזירות אביו ואין האשה מגלחת על נזירות אביה. כיצד\u0004 באיזה אופן אמור דין זה? \u0003מי שהיה אביו נזיר והפריש מעות סתומים על נזירותו\u0004 (שלא פירש אלו מעות הוא מפריש לצורך כל קרבן מקרבנות נזירותו), \u0003ומת\u0004 לפני שקנה את הקרבנות. \u0003ואמר\u0004 הבן לאחר מות אביו \u0003\"הריני נזיר על מנת שאגלח על מעות\u0004 שהפריש \u0003אבא\".\u0004","\u0003אמר ר' יוסי:\u0004 במקרה כזה \u0003הרי\u0004 מעות \u0003אלו יפלו לנדבה\u0004 ואין הבן מגלח עליהם, כי \u0003אין זה\u0004 שייך להלכה שאמרו שהבן \u0003מגלח על נזירות אביו. איזהו שמגלח על נזירות אביו —\u0004 \u0003מי שהיה הוא ואביו נזירים\u0004 באותה עת, עוד בחיי אביו, \u0003והפריש אביו מעות סתומים לנזירותו, ומת —\u0004 \u0003זה הוא שמגלח על נזירות אביו.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006\u0005]\u0006 ההבדל בין איש לאשה בזה? \u0003אמר ר' יוחנן: הלכה\u0004 למשה מסיני \u0003היא בנזיר.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 מובן מאליו\u0005],\u0006 שכך הוא. וכי \u0003מאי למימרא\u0004 \u0005[מה\u0006 באה לומר\u0005]\u0006 ש\u0003בן יורש את אביו, בת לא,\u0004 ולכן דווקא הבן מגלח על נזירות אביו שכן הוא יורשו, ולא הבת שאינה יורשתו? והרי דבר זה מפורש בכתוב שכאשר יש בן אין הבת יורשת את אביה (ראה במדבר כז, ח)!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה\u0006\u0005]\u0006 ההלכה אלא במקום \u0003דלית ליה\u0004 \u0005[שאין לו\u0006\u0005]\u0006 \u0003אלא בת\u0004 ואז היא היורשת (ראה במדבר כז, ח), \u0003מהו דתימא\u0004 \u0005[שתאמר\u0006\u0005]\u0006 ש\u0003יורשין גמירין לה\u0004 \u0005[למדו אותה\u0006\u0005]\u0006 שהמסורת היתה שהיורשים מגלחים מנכסי המוריש, וכל מי שיורש אביו הריהו גם מגלח על נזירותו, ואף בת בכלל,"],["\u0003קא משמע לן\u0004 \u0005[השמיעה לנו\u0006 המשנה\u0005]\u0006 ש\u0003הלכה\u0004 היא ואינה תלויה בדיני ירושה, אלא כך קיבלו — שהבן בלבד מגלח על נזירות אביו, ולא הבת.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם \u0003פליגי רבנן עליה\u0004 \u0005[חולקים חכמים עליו\u0006\u0005]\u0006 על \u0003ר' יוסי או לא פליגי\u0004 \u0005[חולקים\u0006\u0005]?\u0006 \u0003ואם תימצי\u0004 \u0005[תמצא,\u0006 תרצה\u0005]\u0006 \u0003לומר\u0004 שהם \u0003פליגי\u0004 \u0005[חולקים\u0006\u0005],\u0006 אם כן האם חולקים הם \u0003ארישא\u0004 \u0005[על תחילתה\u0006\u0005]\u0006 \u0003או אסיפא\u0004 \u0005[על סופה\u0006\u0005]\u0006 של ההלכה שאמר? ומביאים פתרון, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 מן הברייתא: \u0003כיצד אמרו\u0004 אופן שבו \u0003האיש מגלח על נזירות אביו?\u0004","— \u0003מי שהיה אביו נזיר והפריש אביו מעות לנזירותו, ומת, ואמר\u0004 הבן \u0003\"הריני נזיר על מנת שאגלח על מעות אבא\" —\u0004 \u0003זהו שמגלח על מעות אביו. אבל מי שהיה הוא ואביו נזירים והפריש אביו מעות לנזירותו ומת —\u0004 \u0003הרי אלו יפלו לנדבה,\u0004 אלו \u0003דברי ר' יוסי.\u0004","\u0003ר' אליעזר ור' מאיר ור' יהודה אמרו: זה הוא שמגלח על מעות אביו.\u0004 ומן ההדגשה \"זה הוא\" משמע שהם חולקים על ר' יוסי לגמרי, ובמקרה שאמר ר' יוסי שמגלח על נזירות אביו סבורים הם שאינו מגלח, ולהיפך, במקרה שסבור ר' יוסי שאינו מגלח סבורים הם שמגלח.","\u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רבה: יש לו שני בנים נזירים מהו?\u0004 וצדדי השאלה: האם נאמר \u0003הילכתא גמירין לה\u0004 \u0005[הלכה אנו למודים אותה\u0006\u0005]\u0006 שהבן מגלח על נזירות אביו, ולכן \u0003כל\u0004 מי \u0003דקדים\u0004 \u0005[שקודם\u0006\u0005]\u0006 מבין שני הבנים, ו\u0003גלח\u0004 \u0005[מגלח\u0006\u0005]\u0006 על נזירות אביו — \u0003גלח\u0004 \u0005[מגלח\u0006\u0005]\u0006 וזוכה בכל הכסף, \u0003או דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 מדין \u0003ירושה\u0004 \u0003גמירין לה\u0004 \u0005[למודים\u0006 אנו אותה\u0005]\u0006 \u0003ו\u0004לכן \u0003פלגא הוי\u0004 \u0005[חצי הוא\u0006\u0005],\u0006 שכל אחד מהם מקבל? בדומה לזה \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 גם \u0003רבא:\u0004 אם היו שני הבנים הנזירים אחד \u0003בכור ו\u0004אחד \u0003פשוט, מאי\u0004 \u0005[מה\u0006\u0005]\u0006 יהא הדין? האם \u0003הילכתא גמירין לה\u0004 \u0005[\u0006בהלכה למודים אותה\u0005]\u0006 שבן מגלח, מקבל דמי תגלחת על נזירות אביו, ואין זה מדיני ירושה, \u0003והילכך לא בעי גלוחי לפום מאי דשקיל\u0004 \u0005[ולכן אינו צריך לגלח,\u0006 לפי מה שמקבל\u0005]\u0006 כל בן בירושתו, אלא כל אחד יקבל חצי, או כל הקודם יזכה. \u0003או דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003ירושה היא, וכי היכי דשקיל\u0004 \u0005[וכמו שהוא,\u0006 הבכור, נוטל\u0005]\u0006 בנכסים בכלל \u0003פי שנים, הכי\u0004 \u0005[כך\u0006\u0005]\u0006 גם \u0003מגלח,\u0004 מקבל בדמי התגלחת פי שנים?","","\u0003ואם תימצי\u0004 \u0005[תמצא\u0006\u0005]\u0006 \u0003לומר: ירושה היא, ולפום\u0004 \u0005[ולפי\u0006\u0005]\u0006 מה \u0003דשקיל\u0004 \u0005[שנוטל\u0006 בנכסים\u0005]\u0006 \u0003מגלח, ו\u0004אולם \u0003ב\u0004עניינים של \u0003חולין הוא דאית ליה\u0004 \u0005[שיש לו\u0006\u0005]\u0006 לבכור \u0003פי שנים, אבל בהקדש —\u0004 \u0003לא. או דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003כיון דקני ליה\u0004 \u0005[שקונה אותו\u0006\u0005]\u0006 ממון \u0003לגלוח,\u0004 שהרי בן מגלח על נזירות אביו, \u0003לא שנא\u0004 \u0005[אינו שונה\u0006\u0005]?\u0006","ועוד יש לשאול: היה \u0003אביו נזיר עולם והוא נזיר סתם,\u0004 או \u0003אביו נזיר סתם והוא נזיר עולם, מאי\u0004 \u0005[מה\u0006\u0005]\u0006 הדין לענין תגלחת הבן על נזירות אביו? האם לומר: \u0003כי גמירין הילכתא\u0004 \u0005[כאשר למדנו\u0006 את ההלכה\u0005]\u0006 שבן מגלח על נזירות אביו, הרי זה כששניהם האב והבן נזירים \u0003בסתם נזירות, או דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה\u0006\u0005],\u0006 והוא הדין אם כל אחד מהם נזיר מסוג אחר?","\u0003ואם תימצי\u0004 \u0005[תמצא\u0006\u0005]\u0006 \u0003לומר: הכא אידי ואידי\u0004 \u0005[כאן זה וזה\u0006\u0005]\u0006 יש בהם מכל מקום צד שווה, ששניהם נדרי \u0003נזירות טהרה,\u0004 ולכן בן מגלח על נזירות אביו, \u0003בעי\u0004 \u0005[שאל\u0006\u0005]\u0006 \u0003רב אשי:\u0004 אם היה \u0003אביו נזיר טמא והוא נזיר טהור\u0004 או היה \u0003אביו נזיר טהור והוא נזיר טמא, מאי\u0004 \u0005[מה\u0006\u0005]\u0006 יהא הדין? האם מגלח במעות אביו, או לא? לכל השאלות הללו לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד\u0006\u0005]\u0006 השאלה במקומה.","","\u0003בית שמאי אומרים: הקדש\u0004 שהקדיש אדם מתוך \u0003טעות,\u0004 מכל מקום \u0003הקדש\u0004 הוא,"],["\u0003ובית הלל אומרים: אין\u0004 זה \u0003הקדש. כיצד\u0004 הוא הקדש טעות? \u0003אמר \"שור שחור שיצא מביתי ראשון הרי הוא הקדש\" ויצא\u0004 ראשון שור שצבעו \u0003לבן, בית שמאי אומרים: הקדש\u0004 הוא, \u0003ובית הלל אומרים: אינו הקדש.\u0004 או אמר \u0003\"דינר זהב שיעלה בידי ראשון\u0004 מכיסי \u0003הרי הוא הקדש\"\u0004 והושיט ידו לכיס \u0003ועלה\u0004 בידו דינר \u0003של כסף, בית שמאי אומרים: הקדש, ובית הלל אומרים: אינו הקדש.\u0004 וכן אם אמר \u0003\"חבית של יין שתעלה בידי ראשונה\u0004 שאמצא כשאכנס למרתף \u0003הרי היא הקדש\" ועלתה\u0004 בידו במקום זה חבית \u0003של שמן, בית שמאי אומרים: הקדש, ובית הלל אומרים: אינו הקדש.\u0004","שנינו במשנה ש\u0003בית שמאי אומרים: הקדש\u0004 טעות — הקדש, ובית הלל אומרים: אינו הקדש. ומבררים את השיטות: \u0003מאי טעמייהו\u0004 \u0005[מה טעמם\u0006\u0005]\u0006 של \u0003בית שמאי —\u0004 \u0003דילפינן\u0004 \u0005[שאנו למדים\u0006\u0005]\u0006 דין \u0003תחלת הקדש מסוף הקדש,\u0004 ומהו סוף הקדש — תמורה, שממיר בהמת קודש בבהמה אחרת. \u0003מה תמורה\u0004 יודעים אנו כי \u0003אפילו בטעות\u0004 היא חלה, שאם נתכוון לומר שתהא זו תמורת שור שחור ואמר \"הרי זו תמורת שור לבן\" — הריהי תמורת השור הלבן, \u0003אף הקדש\u0004 בתחילה \u0003אפילו בטעות\u0004 הוא חל.","\u0003ובית הלל אומרים: הני מילי\u0004 \u0005[דברים אלה\u0006\u0005]\u0006 שהקדושה חלה אף בטעות אמורים דווקא ב\u0003תמורה,\u0004 שבאה מכוח דבר שהיה הקדש גמור. \u0003אבל אחותי\u0004 \u0005[להוריד\u0006\u0005]\u0006 להחיל מתחילה דין \u0003הקדש\u0004 על דבר \u0003בטעות —\u0004 \u0003לא מחתינן\u0004 \u0005[אנו מורידים\u0006\u0005].\u0006","ושואלים: \u0003ול\u0004דעת \u0003בית שמאי,\u0004 שלמדים מתמורה, \u0003מה אילו אמר\u0004 בתחילת היום \u0003\"הרי זה\u0004 תמורה \u0003תחת זה ל\u0004כשיגיע \u0003חצי היום\" מי הויא\u0004 \u0005[האם היא\u0006\u0005]\u0006 נעשית \u0003תמורה מההיא שעתא\u0004 \u0005[מאותה שעה\u0006\u0005]\u0006 שהמיר, בניגוד לדברים שהוציא מפיו? \u0003אלא\u0004 ודאי גם הם מודים כי אינה נעשית תמורה \u0003עד דמטי\u0004 \u0005[שמגיע\u0006\u0005]\u0006 \u0003חצי היום\u0004 שאז \u0003הוא דהויא\u0004 \u0005[שתהיה\u0006\u0005]\u0006 \u0003תמורה. הכי נמי\u0004 \u0005[כך גם כן\u0006\u0005]\u0006 במשנתנו \u0003לכי מיגליא מילתא\u0004 \u0005[כאשר מתגלה הדבר\u0006\u0005]\u0006 כדבריו, שיצא שור שחור תחילה — רק אז חל ההקדש, ואם לא יצא שור שחור תחילה — אין ההקדש חל!","\u0003אמר רב פפא:\u0004 טעמם של בית שמאי אינו משום שלמדו מדין תמורה, ופירוש דברי בית שמאי אינו שהשור הלבן מתקדש. אלא \u0003לכך נאמר,\u0004 זו היתה כוונתו כשאמר \u0003\"\u0004שור שחור שיצא מביתי \u0003ראשון\" —\u0004 \u0003לכשיצא\u0004 ה\u0003ראשון\u0004 מבין השוורים השחורים שיש לו, יהיה הוא הקדש, ואף שיצא לבן תחילה — אין זה נחשב כלל.","ומקשים: \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003\"שור שחור\" קאמר\u0004 \u0005[אמר\u0006\u0005],\u0006 \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים\u0006\u0005]\u0006 אף במקרה \u0003דלית ליה\u0004 \u0005[שאין לו\u0006\u0005]\u0006 \u0003אלא האי\u0004 \u0005[\u0006שור שחור זה\u0005]\u0006 בלבד? ואם כן היתה כוונתו כמבואר: שרק אם יצא שורו השחור תחילה יתקדש! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה\u0006\u0005],\u0006 לא נאמרו דברים אלה אלא במקרה \u0003דאית ליה תרין תלתא\u0004 \u0005[שיש לו שניים שלושה\u0006\u0005]\u0006 שוורים שחורים. \u0003ובית הלל אומרים: אם כן,\u0004 שרצה לומר שהוא מקדיש את הראשון שיצא מבין השוורים השחורים, אם כן \"שור שחור \u0003שיצא בראשון\u0004 מביתי\" \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006\u0005]\u0006 לומר. וכיון שלא אמר כן, ודאי נתכוון לראשון ממש.","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רבא מברניש לרב אשי\u0004 להקשות על שיטת רב פפא: אם כדבריו, \u0003האי\u0004 \u0005[\u0006מקרה זה\u0005]\u0006 האם בכלל \u0003הקדש בטעות הוא?\u0004 הרי \u0003הקדש בכוונה הוא!\u0004 שהרי לפי הסברו של רב פפא לא היתה טעות בעצם ההקדש, שהרי מה שנתכוון להקדיש — הראשון מבין השוורים השחורים — הוא זה שהקדיש. אלא אירעה תקלה שיצא לבן קודם, והוא אינו נחשב! ומשיבים: בכל זאת נקרא זה \"הקדש טעות\", \u0003משום דאטעייה לדיבוריה קמא\u0004 \u0005[שהטעה את דיבורו הראשון\u0006\u0005],\u0006 שאם נתכוון לשור שחור, כפי שפתח בדבריו — צריך היה לומר \"שיצא בראשון\". ויש בזה טעות בסגנון ההקדש. ומכל מקום עולה כי לדעת רב פפא בית שמאי אינם סבורים שהקדש טעות ממש הריהו הקדש.","ושואלים על שיטה זו של רב פפא: \u0003וסברי\u0004 \u0005[ו\u0006כי סבורים\u0005]\u0006 \u0003בית שמאי\u0004 ש\u0003הקדש בטעות\u0004 ממש, \u0003לא הוי\u0004 \u0005[אינו\u0006\u0005]\u0006 \u0003הקדש? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה בהמשך\u0005]:\u0006 \u0003מי שנדר בנזיר ונשאל לחכמים והתירו\u0004 לו את נזרו, \u0003והיתה לו\u0004 כבר \u0003בהמה מופרשת\u0004 לקרבן נזירותו — \u0003תצא ותרעה בעדר\u0004 ככל בהמת חולין.","\u0003אמרו בית הלל לבית שמאי: אי\u0004 (אין) \u0003אתם מודים\u0004 שטעמו של דין זה משום \u0003שהקדש בטעות הוא,\u0004 ואף אתם מודים שאין זה הקדש \u0003ו\u0004וזה הטעם ש\u0003תצא ותרעה בעדר?!\u0004 ואם כן אף בכל הקדש טעות יהא הדין כן — שאינו הקדש! \u0003מכלל\u0004 הדברים אתה למד \u0003דסברי\u0004 \u0005[שסבורים\u0006\u0005]\u0006 \u0003בית שמאי\u0004 ש\u0003הקדש בטעות הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003הקדש,\u0004 לכן הקשו עליהם בית הלל!","ומשיבים: \u0003אלא בית הלל הוא דקא טעו\u0004 \u0005[שטעו\u0006\u0005]\u0006 בהבנת הדברים, \u0003סברי\u0004 \u0005[סבורים\u0006 היו\u0005]\u0006 כי \u0003טעמייהו\u0004 \u0005[טעמם\u0006\u0005]\u0006 של \u0003בית שמאי משום\u0004 ש\u0003הקדש בטעות הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003הקדש,\u0004 ולכן הקשו עליהם מדין נזיר. \u0003ואמרי להון\u0004 \u0005[ואמרו להם\u0006\u0005]\u0006 \u0003בית שמאי:\u0004 טעמו של דבר \u0003לאו\u0004 \u0005[לא\u0006\u0005]\u0006 \u0003משום הקדש בטעות הוא, אלא משום דאטעייה לדיבוריה קמא\u0004 \u0005[שהטעה את דיבורו הראשון\u0006\u0005],\u0006 אבל כוונתו היתה להפריש את הראשון מבין השוורים השחורים.","ושואלים עוד: \u0003וסברי\u0004 \u0005[ו\u0006האם סבורים\u0005]\u0006 \u0003בית שמאי\u0004 כי \u0003הקדש בטעות\u0004 ממש \u0003לא הוי\u0004 \u0005[אינו\u0006\u0005]\u0006 \u0003הקדש? תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 שכן, ממה ששנינו: \u0003היו\u0004 מספר אנשים \u0003מהלכין בדרך,\u0004"],["\u0003ו\u0004היה אדם \u0003אחד בא כנגדן, ואמר אחד\u0004 מהמהלכים: \u0003\"הריני נזיר שזה\u0004 (אם זה) שהולך לקראתנו הוא \u0003פלוני\", ואחד\u0004 מהם \u0003אמר \"הריני נזיר שאין זה\u0004 (אם אין זה) \u0003פלוני\",\u0004 והיה שם שלישי שאמר להם: \u0003\"הריני נזיר שאחד\u0004 (אם אחד) \u0003מכם\u0004 משניכם הוא \u0003נזיר\"\u0004 והיה אחד שאמר: \u0003\"\u0004הריני נזיר \u0003שאין\u0004 (אם אין) \u0003אחד מכם נזיר\",\u0004 והיה אחד שאמר: \u0003\"\u0004הריני נזיר \u0003ששניכם נזירים\",\u0004 והיה עוד אחד שאמר \u0003\"\u0004הריני נזיר ש\u0003כולכם\u0004 — כל אלה שדיברו קודם — \u0003נזירים\". בית שמאי אומרים: כולם נזירים,\u0004 שכיון שכל אחד מהם אמר \"הריני נזיר\" חל עליו נדר נזירות למרות שלא כיוון לאמת.","\u0003והא הכא\u0004 \u0005[והרי כאן\u0006\u0005]\u0006 \u0003הקדש בטעות\u0004 ממש \u0003הוא,\u0004 שהרי בוודאי אחדים מהם טעו, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנה\u0006\u0005]\u0006 לדעת בית שמאי: \u0003כולם נזירים! אמרי\u0004 \u0005[אומרים\u0006\u0005]:\u0006 באמת \u0003סברי\u0004 \u0005[סבורים\u0006\u0005]\u0006 \u0003בית שמאי\u0004 ש\u0003הקדש בטעות הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003הקדש\u0004 בדרך כלל, ודבר זה אפשר ללמוד מן ההלכה לענין הנזירים, אבל \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 במשנה שלנו, לענין שור שחור ולבן \u0003לא\u0004 בזה מדובר, אלא כפי שפירשו רב פפא.","\u0003אביי אמר\u0004 שיש להבין את המשנה בדרך אחרת: \u0003לא קא סלקא דעתך\u0004 \u0005[יעלה על דעתך\u0006\u0005]\u0006 לומר שמדובר \u0003דקאים בצפרא\u0004 \u0005[שעמד,\u0006 שקם, בבוקר\u0005]\u0006 ואמר על דבר שיהיה (שיצא) בעתיד, \u0003אלא הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים\u0006\u0005]\u0006 \u0003דקאים בטיהרא\u0004 \u0005[שעמד בצהרים\u0006\u0005]\u0006 לאחר שכבר יצאו השוורים מן הבית, \u0003ואמר: שור שחור שיצא מביתי ראשון ליהוי\u0004 \u0005[שיהיה\u0006\u0005]\u0006 \u0003הקדש,\u0004 שאינו מדבר על דבר העתיד לקרות, אלא על דבר שכבר היה. \u0003ואמרו ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 שור \u0003לבן נפק\u0004 \u0005[יצא\u0006\u0005]\u0006 ראשון. \u0003ואמר להון\u0004 \u0005[להם\u0006\u0005]:\u0006 \u0003אי הוה ידענא\u0004 \u0005[אם הייתי יודע\u0006\u0005]\u0006 ש\u0003לבן נפק\u0004 \u0005[יצא\u0006\u0005]\u0006 \u0003לא אמרי\u0004 \u0005[הייתי אומר\u0006\u0005]\u0006 \u0003שחור.\u0004 ונמצא שהיה זה אכן הקדש בטעות.","ומקשים: \u0003ומי מצית אמרת\u0004 \u0005[והאם יכול אתה לומר\u0006\u0005]\u0006 שבמי \u0003דקאים בטיהרא עסיק\u0004 \u0005[שעומד בצהרים אנו עוסקים\u0006\u0005]\u0006 במשנה, שהמקדיש מדבר על מאורע שכבר היה? \u0003והקתני\u0004 \u0005[והרי שנינו\u0006\u0005]\u0006 בהמשך דינו של זה שאמר: \u0003\"דינר של זהב שיעלה\u0004 בידי ראשון הרי הוא הקדש \u0003\",\u0004 ומלשון זו ברור שהוא מדבר על דבר העתיד להיות! ומשיבים: \u0003תני\u0004 \u0005[שנה,\u0006 תקן\u0005]\u0006 \u0003\"\u0004דינר של זהב \u0003שעלה\",\u0004 בלשון עבר. ועוד שואלים: הרי שנינו: \u0003\"חבית של יין שתעלה\u0004 בידי ראשונה הרי היא הקדש \u0003\"\u0004בלשון עתיד! ומשיבים: \u0003תני\u0004 \u0005[שנה\u0006\u0005]\u0006 \u0003\"\u0004חבית \u0003שעלתה\",\u0004 גם כן בלשון עבר.","ואגב שהוזכרו במשנה שור שחור ולבן, מביאים מה ש\u0003אמר רב חסדא:\u0004 שור \u0003אוכמא בחיורא\u0004 \u0005[שחור בין לבנים\u0006\u0005] —\u0006 \u0003לקיא\u0004 \u0005[ליקוי,\u0006 חסרון, הוא\u0005]\u0006 כי השוורים הלבנים הם המובחרים, \u0003חיורא באוכמא\u0004 \u0005[\u0006כתם לבן בשור שחור\u0005]\u0006 \u0003לקיא —\u0004 \u0005[ליקוי,\u0006 חסרון, הוא\u0005].\u0006 ודנים בדבר, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003\"שחור שיצא מביתי ראשון הקדש\"\u0004 ויצא לבן. \u0003קא סלקא דעתין\u0004 \u0005[עולה על דעתנו\u0006\u0005]\u0006 בהנחה פשוטה לומר: \u0003כי\u0004 \u0005[כאשר\u0006\u0005]\u0006 אדם \u0003מקדיש\u0004 דבר להקדש — \u0003בעין רעה\u0004 הוא \u0003מקדיש,\u0004 כלומר, המקדיש אינו מתכוון לתת את המובחר שיש לו, אלא דווקא את הפחות שבנכסיו, \u0003ו\u0004בכל זאת \u0003אמרי\u0004 \u0005[אומרים\u0006\u0005]\u0006 \u0003בית שמאי\u0004 כי \u0003הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003הקדש,\u0004 שהשור הלבן נעשה הקדש, משמע שאין הלבן מובחר, ולא כדברי רב חסדא!","ומבררים את הנחת היסוד של הקושיה: \u0003ואלא מאי\u0004 \u0005[מה\u0006\u0005]\u0006 תאמר, שבית שמאי סבורים כי \u0003בעין יפה\u0004 אדם \u0003מקדיש\u0004 בדרך כלל, שמתכוון לתת את המובחר בנכסיו? והלא שנינו עוד במשנה: \u0003\"דינר של זהב שיעלה בידי ראשון\" ועלה כסף, בית שמאי אומרים: הקדש.\u0004 משמע שאין כוונתו של מקדיש לתת דווקא את המובחר, שהרי כסף בוודאי שווה פחות מזהב!","ומקשים כנגד הנחת יסוד זו: \u0003ואלא מאי\u0004 \u0005[מה\u0006\u0005]\u0006 אתה אומר — \u0003בעין רעה מקדיש?\u0004 הלא נאמר בהמשך המשנה \u0003\"חבית של יין שתעלה בידי ראשון\" ועלה של שמן, בית שמאי אומרים: הקדש.\u0004 \u0003והא\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003שמן עדיף מיין\u0004 ומדוע יהיה זה הקדש! ומשיבים: \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003משום הא\u0004 \u0005[זה\u0006\u0005]\u0006 \u0003לא קשיא\u0004 \u0005[אין\u0006 זה קשה\u0005],\u0006 \u0003בגלילא\u0004 \u0005[בגליל\u0006\u0005]\u0006 \u0003שנו\u0004 משנה זו, \u0003דחמרא\u0004 \u0005[שיין\u0006\u0005]\u0006 \u0003עדיף ממשחא\u0004 \u0005[משמן\u0006\u0005]\u0006 בגליל, שהזיתים גדלים שם הרבה, והשמן זול מן היין. ואם כן אפשר לפרש כל האמור במשנה כשיטה שהמקדיש בעין רעה מקדיש.","ועל כל פנים \u0003רישא קשיא\u0004 \u0005[מהתחלת\u0006 המשנה קשה\u0005]\u0006 \u0003לרב חסדא\u0004 שלפי מה שאמרנו שמקדיש בעין רעה, נמצא ששור לבן פחות משחור! ומשיבים: \u0003אמר\u0004 \u0005[יכול\u0006 היה לומר\u0005]\u0006 \u0003לך רב חסדא: כי אמרי\u0004 \u0005[כאשר אמרתי\u0006\u0005]\u0006 שלבן מעולה יותר — הרי זה דווקא \u0003בתורא דקרמנאי\u0004 \u0005[בשור של הקרמונאים\u0006\u0005]\u0006 ובמין זה של שוורים הלבנים הם המובחרים, אבל בשאר מקומות שוורים שחורים הם המובחרים, ובזה עוסקת המשנה.","\u0003ו\u0004מביאים מה ש\u0003אמר רב חסדא\u0004 עוד בענין של שוורים: \u0003אוכמא\u0004 \u0005[\u0006שור שחור\u0005]\u0006 — טוב \u0003למשכיה\u0004 \u0005[לעורו\u0006\u0005],\u0006 \u0003סומקא\u0004 \u0005[\u0006שור אדום\u0005] —\u0006 \u0003לבשריה\u0004 \u0005[לבשרו\u0006\u0005],\u0006 \u0003חיורא\u0004 \u0005[\u0006שור לבן\u0005] —\u0006 \u0003לרדיא\u0004 \u0005[לחרישה\u0006\u0005].\u0006 ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר\u0006\u0005]\u0006 \u0003רב חסדא: אוכמא בחיורא לקיא\u0004 \u0005[שחור בין הלבנים ליקוי,\u0006 חסרון, הוא\u0005],\u0006 משמע שהשחור גרוע בכל דבר! ומשיבים: יכול רב חסדא לומר: \u0003כי אמרי בתורא דקרמונאי\u0004 \u0005[כאשר אמרתי\u0006 דבר זה דווקא בשור של קרמונאי\u0005],\u0006 אבל באחרים לא.","\u0003מי שנדר בנזיר\u0004 (להיות נזיר) ואחר כך התחרט, ומאותה שעה לא נהג עוד מנהג נזירות בשתיית יין, ואחר כך \u0003נשאל לחכם,\u0004 שביקש שהחכם יתיר לו את נדרו, \u0003ואסרו\u0004 החכם, שלא מצא סיבה להתיר לו את הנדר — \u0003מונה\u0004 את כל ימי נזירותו כפי שקיבל עליו \u0003משעה שנדר,\u0004 ובכללם נמנים גם ימים שנהג בהם היתר. אם \u0003נשאל לחכם והתירו\u0004 ובטל הנדר מעיקרו, הרי אם \u0003היתה לו\u0004 כבר \u0003בהמה מופרשת\u0004 לצורך קרבנות אותה נזירות שהתבטלה — \u0003תצא ותרעה בעדר\u0004 כחולין גמורים.","על בסיס הלכה זו \u0003אמרו בית הלל לבית שמאי\u0004 כהמשך למחלוקתם במשנה הקודמת: \u0003אי\u0004 (אין) \u0003אתם מודים בזה שהוא הקדש טעות ש\u0004בשל כך \u0003תצא ותרעה בעדר?!\u0004 הרי שאף אתם מסכימים שהקדש טעות אינו חל! \u0003אמר\u0004 (אמרו) \u0003להן בית שמאי: אי\u0004 \u0005[\u0006וכי אין\u0005]\u0006 \u0003אתם מודים במי\u0004 שהיה מפריש מעשר בהמה מעדרו שמעביר את הבהמות לפניו אחת אחת, וכל בהמה עשירית שנמנית כשיוצאת מן הדיר מתקדשת בקדושת מעשר, \u0003ש\u0004אם \u0003טעה וקרא לתשיעי \"עשירי\", ולעשירי \"תשיעי\" ולאחד עשר \"עשירי\" שהוא,\u0004 כל אחד מהם, \u0003מקודש?\u0004 הרי שחל הקדש גם בטעות!","\u0003אמרו להם בית הלל: לא השבט\u0004 (השוט) \u0003קידשו,\u0004 כלומר, לא כמו שאתם סבורים שבעל חיים זה מקודש משום שנגע בו השבט, ומשום שאמר שהוא \"עשירי\". כי לא כל טעות מקדשת את המעשר, וראיה לדבר: \u0003ומה אילו טעה והניח את השבט על שמיני ועל שנים עשר\u0004 וקרא להם \"עשירי\" בטעות, \u0003שמא עשה כלום? אלא\u0004 סיבה אחרת לדבר, אותו \u0003כתוב שקידש\u0004 את \u0003העשירי —\u0004 \u0003הוא\u0004 ש\u0003קידש\u0004 גם את \u0003התשיעי.\u0004"],["\u0003ואת אחד עשר,\u0004 שהיא גזירת הכתוב הנלמדת מריבוי המילים שגם אלה מתקדשים. ואין הקדש חל עליהם משום הטעות, אלא משום גזירת הכתוב.","שנינו במשנה כי מי שנדר נזירות ובא לפני חכם ואסרו מונה נזירותו משעה שנדר, ומחשיב בכלל זה ימים שלא נהג נזירות. ושואלים: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת מי היא משנתנו\u0005]?\u0006 הרי אינה \u0003לא\u0004 כדעת \u0003ר' יוסי ולא\u0004 כדעת \u0003רבנן\u0004 \u0005[חכמים\u0006\u0005].\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 \u0003מי שנדר ועבר על נזירותו\u0004 ושתה יין — \u0003אין נזקקין לו\u0004 חכמים להתיר את נדרו אם בא להישאל, ולא להשלים את נזירותו בהקרבת קרבנות, \u0003אלא אם כן מונה בהן\u0004 ימי \u0003איסור כימים שנהג בהם היתר,\u0004 ואחרי שנוהג כהלכה ככל ימי הנזירות שביטל אז מותר להישאל לו, או מתירים לו להביא קרבנותיו. \u0003ר' יוסי אומר: דיו שלשים יום.\u0004 שאם עבר על נזירותו שלושים יום או יותר רק אז נוהגים בו דבר זה (ר\"ת). ומעתה, כשיטתו של מי היא משנתנו?","\u0003אי רבנן\u0004 \u0005[אם\u0006 כדעת חכמים\u0005]\u0006 \u0003קשיא\u0004 \u0005[קשה\u0006\u0005]\u0006 מענין של \u0003נזירות מועטת,\u0004 שלשיטת חכמים אינו יכול למנות בשום מקרה משעת הנדר, אלא צריך להוסיף ימים כימים שעבר ונהג היתר, ואפילו היתה זו נזירות מועטת — מכל מקום צריך להוסיף ימים. \u0003אי\u0004 \u0005[אם\u0006\u0005]\u0006 לדעת \u0003ר' יוסי,\u0004 אף שבנזירות מועטת שנהג היתר בפחות משלושים יום, אינו מצריך להוסיף ימים ומונה משעה שנדר, כמשנתנו, מכל מקום \u0003קשיא\u0004 \u0005[קשה\u0006\u0005]\u0006 מענין של \u0003נזירות מרובה!\u0004 שאף לדעתו צריך להוסיף ימים!","ומשיבים: \u0003איבעית תימא\u0004 \u0005[אם תרצה אמור\u0006\u0005]\u0006 שמשנתנו כדעת \u0003ר' יוסי\u0004 היא, \u0003ואיבעית תימא רבנן\u0004 \u0005[ואם תרצה אמור\u0006 שכדעת חכמים\u0005]\u0006 היא. ומפרטים: \u0003איבעית תימא\u0004 \u0005[אם תרצה אמור\u0006\u0005]\u0006 כשיטת \u0003ר' יוסי: כאן בנזירות מרובה כאן בנזירות מועטת,\u0004 כלומר, יש להבין את משנתנו דווקא במקרה שעבר על נזירותו פחות משלושים יום.","\u0003ואיבעית תימא רבנן\u0004 \u0005[ואם תרצה אמור\u0006 ששיטת חכמים היא משנתנו\u0005],\u0006 וצריך לתקן קצת את לשון המשנה, \u0003לא תימא\u0004 \u0005[תאמר\u0006\u0005]\u0006 שהוא נוהג איסור \u0003משעה שנזר, אלא אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 \u0003כמשעה שנזר,\u0004 כלומר, עליו למנות נזירות ככל הזמן שעבר משעה שנזר. והם ממש דברי חכמים.","שנינו במשנה \u0003\"נשאל לחכמים והתירוהו\u0004 והיתה לו בהמה תצא ותרעה בעדר \u0003\".\u0004 \u0003אמר ר' ירמיה: מ\u0004כלל דברי \u0003בית שמאי,\u0004 שאף הם מסכימים להלכה זו, \u0003נשמע\u0004 \u0005[נלמד\u0006\u0005]\u0006 גם \u0003ל\u0004דברי \u0003בית הלל. לאו אמרי\u0004 \u0005[האם אין אומרים\u0006\u0005]\u0006 \u0003בית שמאי\u0004 ש\u0003הקדש בטעות הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003הקדש,\u0004 ומכל מקום \u0003כיון דאיגלאי מילתא דלאו שפיר\u0004 \u0005[שהתברר הדבר שלא יפה\u0006\u0005]\u0006 \u0003נזר\u0004 והתבטל הנדר מעיקרו — \u0003תצא\u0004 הבהמה לחולין \u0003ותרעה בעדר.\u0004","אף \u0003לבית הלל נמי\u0004 \u0005[גם כן\u0006\u0005],\u0006 \u0003אף על גב דאמרי\u0004 \u0005[אף על פי ש\u0006הם אומרים\u0005]\u0006 שמי שעושה \u0003תמורה\u0004 שממיר בהמת קדשים בבהמה אחרת \u0003בטעות, הויא\u0004 \u0005[הריהי\u0006\u0005]\u0006 \u0003תמורה —\u0004 \u0003הני מילי היכא דאיתיה\u0004 \u0005[דברים אלה\u0006 אמורים דווקא כאשר ישנו\u0005]\u0006 \u0003לעיקר הקדש\u0004 ולכן יכול לעשות תמורה. \u0003אבל היכא דמיתעקר\u0004 \u0005[במקום שנעקר\u0006\u0005]\u0006 \u0003עיקר הקדש,\u0004 שנשאל לחכמים והתירו את נדר ההקדש הראשון, ואין עוד ממשות בקדושה שהתפיס בה — \u0003איתעקר נמי\u0004 \u0005[נעקרת גם כן\u0006\u0005]\u0006 ה\u0003תמורה\u0004 והריהי חולין.","\u0003אמר מר\u0004 \u0005[החכם,\u0006 בית שמאי\u0005]\u0006 במשנה: וכי \u0003אי\u0004 \u0005[אין\u0006\u0005]\u0006 \u0003אתם מודים שאילו קרא לתשיעי עשירי\u0004 שהוא מקודש. ובענין זה \u0003איתמר\u0004 \u0005[נאמר\u0006\u0005]\u0006 שדנו אמוראים: \u0003מעשר\u0004 בהמה, \u0003רב נחמן אמר:\u0004 דווקא \u0003טעותו\u0004 היא שמקדשת אותו, \u0003ולא כוונתו,\u0004 שאם ידע שתשיעי הוא, ובכוונה קרא לו \"עשירי\" כדי לקדשו — אין זה מועיל. \u0003רב חסדא ורבה בר רב הונא אמרי\u0004 \u0005[אומרים\u0006\u0005]:\u0006 \u0003טעותו\u0004 מקדשת, \u0003וכל שכן כוונתו,\u0004 אם נתכוון במפורש לקרוא לתשיעי (או לאחד עשר) \"עשירי\" הגם שידע שאינו עשירי.","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רבא לרב נחמן: לדידך דאמרת\u0004 \u0005[לשיטתך שאתה אומר\u0006\u0005]\u0006 כי \u0003טעותו\u0004 היא המקדשת את התשיעי \u0003ולא כוונתו,\u0004 מה \u0003דקאמרי\u0004 \u0005[שאומרים\u0006\u0005]\u0006 \u0003בית שמאי לבית הלל\u0004 במשנתנו כדי להוכיח להם שהקדש בטעות הקדש הוא: וכי \u0003אי\u0004 \u0005[אין\u0006\u0005]\u0006 \u0003אתם מודים שאילו קרא לתשיעי עשירי ולעשירי תשיעי, ולאחד עשר עשירי ששלשתן מקודשין, ואישתיקו\u0004 \u0005[ושתקו\u0006\u0005]\u0006 \u0003בית הלל\u0004 ולא סתרו את הקושיה הזו מתוך עצמה, אלא ענו באופן אחר.","לשיטתך \u0003לימרו להון\u0004 \u0005[שיאמרו להם\u0006\u0005]\u0006 לבית שמאי תשובה לגוף הדבר: אין ללמוד ממעשר להקדש רגיל, שהרי \u0003מה למעשר —\u0004 \u0003שכן אינו קדוש בכוונה,\u0004 שאם נתכוון על כל התשיעי, העשירי והאחד עשר לקרותם עשירי, אין בכך כלום ואינם קדושים בקדושת מעשר, ולפיכך אין מכאן ראיה להקדש שעיקר קדושתו בכוונה היא.","\u0003אמר רב שימי בר אשי: היינו טעמא\u0004 \u0005[זהו הטעם\u0006\u0005]\u0006 ש\u0003לא אמרי להון\u0004 \u0005[אמרו להם\u0006\u0005]\u0006 תשובה זו, שכן נראים הדברים היפך זה, שכן \u0003קל וחומר הוא: מה מעשר שאינו קדוש בכוונה —\u0004 \u0003קדוש ב\u0004כל זאת על ידי \u0003טעות, הקדש שקדוש בכוונה —\u0004 \u0003לא כל שכן\u0004 שיתקדש בטעות?!","ודוחים: \u0003ולא היא\u0004 (ואין הדבר כן) שאין זה קל וחומר, שכן \u0003הקדש בדעתא דמריה תלי\u0004 \u0005[בדעת בעליו\u0006 הוא תלוי\u0005]\u0006 ולכן אינו יכול להתקדש על ידי טעות. אבל המעשר איננו הקדש מתוך דעת הבעלים ורצונם, אלא על פי חשבון, שהעשירי למנין הבהמות הוא קודש.","\u0003מי שנדר בנזיר והלך להביא את בהמתו\u0004 שהפריש לצורך קרבן הנזירות \u0003ומצאה\u0004 (גילה) \u0003שנגנבה,\u0004 והוא מתחרט עכשיו על עצם הנזירות שקיבל על עצמו משום שאין לו עתה בהמה להקריב. \u0003אם עד שלא\u0004 (לפני) \u0003נגנבה בהמתו נזר —\u0004 \u0003הרי זה נזיר,\u0004 ואין זה פתח להתיר את נדרו, שאין מתירים נדר בשל מאורע ששינה את מצב הדברים לאחר זמן."],["\u0003ואם משנגנבה בהמתו נזר —\u0004 \u0003אינו נזיר,\u0004 שהרי התברר שהיתה נזירותו בטעות מתחילה, שכן בשעה שנזר לא היתה לו כל בהמה לקרבנותיו ואילו הוא סמך בדעתו עליה. \u0003וזו טעות טעה נחום המדי\u0004 שלא הבדיל בין דבר שאירע לפני הנדר לבין דבר שאירע אחריו. שכך היה מעשה: \u0003כשעלו נזירים מן הגולה\u0004 להקריב קרבנות \u0003ומצאו בית המקדש חרב. אמר להם נחום המדי: אילו הייתם יודעין שבית המקדש חרב הייתם נוזרים? אמרו לו:\u0004 בוודאי ש\u0003לא,\u0004 שהרי אין תקנה לנזירות כזו. \u0003והתירן נחום המדי.\u0004","\u0003וכשבא הדבר אצל חכמים אמרו:\u0004 אין הדבר כן, אלא \u0003כל שנזר עד שלא חרב בית המקדש\u0004 כנזירים אלו שעלו מן הגולה — הריהו \u0003נזיר,\u0004 שהרי בשעה שנזר לא היתה בכך טעות, ואין מתירים לו את נזירותו על סמך זה. אבל מי שנדר \u0003מש\u0004כבר \u0003חרב בית המקדש —\u0004 \u0003אינו נזיר,\u0004 כיון שהתברר שנזר בטעות.","בעקבות האמור במשנה בענין התרת נדר נזירות בעקבות דבר שאירע לאחר מכן, מביאים מה ש\u0003אמר רבה: שטפוהו\u0004 \u0005[עקרוהו,\u0006 סחפוהו\u0005]\u0006 \u0003רבנן\u0004 \u0005[חכמים\u0006\u0005]\u0006 \u0003לר' אליעזר\u0004 והוציאוהו משיטתו, \u0003ואוקמיה בשיטתייהו\u0004 \u0005[והעמידוהו בשיטתם\u0006\u0005].\u0006 ומה עניינו: \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]\u0006 במסכת נדרים: \u0003פותחין בנולד,\u0004 כלומר, כאשר באים להתיר נדר — פותחים להתיר גם בדבר שהנודר לא ידע בשעה שנדר שעתיד הוא לבוא, אלו \u0003דברי ר' אליעזר, וחכמים אוסרין.\u0004 ואילו במשנתנו העוסקת בנדר נזירות לא חלק ר' אליעזר, משמע שקיבל את דעת חכמים.","\u0003ו\u0004עוד בענין זה, \u0003אמר רבא: אף על גב דאמור רבנן\u0004 \u0005[אף על פי שאמרו חכמים\u0006\u0005]\u0006 \u0003אין פותחין בנולד —\u0004 \u0003אבל פותחין בתנאי נולד.\u0004 כלומר, אפשר לפתוח פתח להתיר נדר באופן דומה לנולד. \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הוא הדבר\u0006\u0005]\u0006 לענין שהבאנו? \u0003אמרי להון\u0004 \u0005[אומרים להם\u0006\u0005]\u0006 החכמים המתירים לנזירים שנזרו לפני שנחרב חורבן בית המקדש: \u0003אילו אתא איניש\u0004 \u0005[היה בא אדם\u0006\u0005]\u0006 \u0003ואמר לכון\u0004 \u0005[ו\u0006היה אומר לכם\u0005]\u0006 \u0003דחרב\u0004 \u0005[שיחרב\u0006\u0005]\u0006 \u0003בית המקדש, מי הוה נדריתון\u0004 \u0005[האם הייתם נודרים\u0006\u0005]?\u0006 ובמקרה זה, אם יענו בשלילה, הרי אף שהחורבן עצמו נולד הוא — אבל האפשרות לחורבנו היתה קיימת כבר בשעת נדרם, ובאופן זה מתירים את הנדר.","\u0003אמר רב יוסף: אי הואי התם\u0004 \u0005[אם הייתי שם\u0006\u0005]\u0006 בזמן שבאו אותם נזירים עליהם מסופר במשנה, \u0003הוה אמינא להון\u0004 \u0005[הייתי אומר להם\u0006\u0005]\u0006 כדי להתירם: \u0003הכתיב\u0004 \u0005[הרי נאמר\u0006\u0005]\u0006 \u0003\"היכל ה' היכל ה' היכל ה' המה\"\u0004 (ירמיה ז, ד), ששלוש פעמים שנאמר \"היכל ה'\" — \u0003זה מקדש ראשון ומקדש שני\u0004 שעתידים להיחרב (ויהיה עוד היכל שלישי). ואם כן היו צריכים להעלות על דעתם שייחרב המקדש, ויוכל הדבר לשמש להם כפתח להיתרם.","ומשיבים: \u0003נהי דידעין להון דיחרוב\u0004 \u0005[אם אמנם שיודעים שיחרב\u0006\u0005]\u0006 המקדש השני, שהרי כאמור נאמרו בפסוק שלושה בתי מקדש, אך \u0003מי\u0004 \u0005[האם\u0006\u0005]\u0006 \u0003יודעין לאימתי\u0004 יחרב, ויעלו בדעתם שיהיה זה בימיהם ולא יוכלו להקריב קרבנות נזירותם? \u0003אמר אביי: ולא ידעין לאימת\u0004 \u0005[ו\u0006כי אין יודעים מתי\u0005]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר\u0006\u0005]:\u0006 \u0003\"שבעים שבעים נחתך על עמך\u0004 \u0003ועל עיר קדשך\"\u0004 (דניאל ט, כד) ומכאן למדים ששבעים שמיטות (שבועות) שהם ארבע מאות ותשעים שנה אחר חורבן בית ראשון יחרב הבית השני! ומשיבים: \u0003ואכתי מי ידעינן בהי יומא\u0004 \u0005[ועדיין האם אנו יודעים באיזה יום\u0006\u0005]\u0006 ייחרב? ואם כן אי אפשר היה לפתוח להם פתח מכאן.","\u0003היו\u0004 ששה אנשים \u0003מהלכין בדרך, ואחד בא כנגדן, אמר אחד מהן\u0004 מן ההולכים: \u0003\"הריני נזיר\u0004 אם \u0003שזה\u0004 ההולך לקראתנו הוא \u0003פלוני\", ואחד\u0004 מהם \u0003אמר: \"הריני נזיר שאין זה פלוני\",\u0004 ושלישי אמר לאותם שניים \u0003\"הריני נזיר שאחד מכם נזיר\",\u0004 והיה רביעי שאמר לשניים הראשונים: \u0003\"\u0004הריני נזיר \u0003שאין אחד מכם נזיר\",\u0004 והיה חמישי שאמר לשניים הראשונים: \u0003\"\u0004הריני נזיר \u0003ששניכם נזירים\",\u0004 ושישי אמר: \u0003\"\u0004הריני נזיר \u0003שכולכם,\u0004 כל הקודמים לי, \u0003נזירים\".\u0004","\u0003בית שמאי אומרים: כולן נזירין,\u0004 ואף אלו שטעו, לפי שהוציאו נדר נזירות מפיהם, ונזירות אף בטעות — נזירות היא, לשיטתם. \u0003ובית הלל אומרים: אינו נזיר אלא מי שלא נתקיימו דבריו. ור' טרפון אומר: אין אחד מהם נזיר,\u0004 ואף זה שנתקיימו דבריו אינו נזיר, משום שלדעתו אין נדר הנזירות חל אלא בזמן שנודר בוודאות ולא מחמת ספק. ואילו במקרה זה לא ידע אף אחד בוודאות מי הוא הבא לקראתם ומה דינם של השניים הראשונים.","אם אותו אדם שבא כנגדם שעליו נחלקו מי הוא \u0003הרתיע\u0004 (חזר) \u0003לאחוריו\u0004 ולא התברר מי הוא — אף אחד \u0003אינו נזיר,\u0004 שהרי לא בא הדבר לידי בירור, וספק נזירות — להקל. \u0003ר' שמעון אומר:\u0004 יש להחמיר בספק זה, וכך יש לעשות כדי לצאת מכל ספק: \u0003יאמר\u0004 כל אחד מהנודרים הללו \u0003\"אם היה כדברי —\u0004 \u0003הריני נזיר חובה\",\u0004 שהרי נתקיימו דבריו, \u0003ואם לאו\u0004 \u0005[לא\u0006\u0005] —\u0006 \u0003\"הריני נזיר נדבה\"\u0004 וינהג בנזירות לכל דבר.","שנינו במשנה שלדעת בית הלל רק \u0003מי שלא נתקיימו דבריו\u0004 הריהו נזיר. ותוהים: \u0003אמאי הוי\u0004 \u0005[מדוע יהיה\u0006\u0005]\u0006 \u0003נזיר?\u0004 הרי לא התקיימו דבריו! \u0003אמר רב יהודה: אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 תקן הלשון במשנה ונסח כך: \u0003מי שנתקיימו דבריו\u0004 הוא שנעשה נזיר."],["\u0003אביי אמר:\u0004 צריך לתקן את סגנון הדברים במשנה ולומר: \u0003כגון\u0004 ש\u0003אמר\u0004 נוסף לדבריו הראשונים: \u0003\"אי נמי לאו\u0004 \u0005[אם גם לא\u0006\u0005]\u0006 \u0003פלוני הוא —\u0004 \u0003אי הוי\u0004 \u0005[אהיה\u0006\u0005]\u0006 \u0003נזיר\". ומאי\u0004 \u0005[ומה\u0006\u0005]\u0006 פירוש \u0003\"לא נתקיימו דבריו\"\u0004 — הכוונה היא: אף ש\u0003לא נתקיימו דבריו הראשונים,\u0004 שלא היה זה פלוני, \u0003אלא דבריו אחרונים\u0004 נתקיימו — אף בכגון זה הריהו נזיר.","שנינו במשנה: \u0003\"הרתיע לאחוריו\u0004 ולא נודע מי היה האיש — \u0003אינו נזיר\" כו'.\u0004 ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003משום\u0004 ש\u0003הרתיע לאחוריו, הא אתי לקמן\u0004 \u0005[הרי\u0006 אם היה בא לפנינו\u0005]\u0006 אותו האיש והיינו מזהים אותו — \u0003הוי\u0004 \u0005[הריהו\u0006\u0005]\u0006 \u0003נזיר,\u0004 אותו אדם שאמר שיהיה נזיר אם זה פלוני. ומבררים: \u0003מני\u0004 \u0005[\u0006כשיטת מי היא\u0005]\u0006 הלכה זו?"],[],["\u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 שיטת \u0003ר' טרפון\u0004 היא — \u0003מי הוי\u0004 \u0005[האם הוא\u0006\u0005]\u0006 \u0003נזיר\u0004 אף אם בא אותו אדם לפנינו, והיה זה כדבריו של אחד מהם? והרי \u0003כיון דבשעתא דקא נזר\u0004 \u0005[שבשעה שנזר\u0006\u0005]\u0006 \u0003לא ידע אי\u0004 \u0005[אם\u0006\u0005]\u0006 \u0003פלוני הוא ואי\u0004 \u0005[ואם\u0006\u0005]\u0006 \u0003לא, מי\u0004 \u0005[האם\u0006\u0005]\u0006 \u0003חלה עליה\u0004 \u0005[עליו\u0006\u0005]\u0006 \u0003נזירות? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר משום\u0004 (בשם) \u0003ר' טרפון:\u0004 במקרה של משנתנו \u0003אין אחד מהן,\u0004 מכל השישה הנזכרים במשנה, \u0003נזיר, לפי שלא נתנה נזירות אלא להפלאה!\u0004 כיון שנאמר בתורה בענין קבלת נזירות לשון הפלאה (\"כי יפליא לנדור נדר נזיר\". במדבר ו, ב) ומשמעה: הפרשה וברירות. ובמקום שאין הדבר ברור, אין כאן נדר נזירות. \u0003אלא\u0004 שיטת \u0003ר' יהודה\u0004 בשם עצמו, וכפי שפסק לענין \u0003כרי הוא. דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]\u0006 אמר אדם \u0003\"הריני נזיר על מנת שיהא בכרי\u0004 (ערימת תבואה) \u0003הזה מאה כור\u0004 (מידת נפח) \u0003\"\u0004\u0003והלך\u0004 למודדו \u0003ומצאו\u0004 (גילה) \u0003שנגנב\u0004 הכרי או חלקו, \u0003או שאבד,\u0004 ואי אפשר עכשיו לדעת כמה היה בו — \u0003ר' שמעון אוסר\u0004 בכל איסורי נזיר את האיש משום ספק, שמא היה בכרי מאה כור. \u0003ור' יהודה מתיר,\u0004 שהוא סבור כי ספק נזירות להקל. והוא הדין במשנתנו. ו\u0003ר' שמעון\u0004 החולק במשנתנו \u0003סבר\u0004 \u0005[סבור\u0006\u0005]\u0006 בענין כרי: \u0003כיון\u0004 ש\u0003אילו לא\u0004 היה הכרי \u0003נגנב דלמא הוו ביה\u0004 \u0005[שמא היו בו\u0006\u0005]\u0006 \u0003מאה כור והוי\u0004 \u0005[והריהו\u0006\u0005]\u0006 \u0003נזיר, השתא נמי הוי\u0004 \u0005[עכשיו גם כן הריהו\u0006\u0005]\u0006 \u0003נזיר\u0004 מספק. \u0003והכא נמי\u0004 \u0005[וכאן\u0006 במשנתנו גם כן\u0005]\u0006 \u0003כיון דאי אתא לקמן\u0004 \u0005[שאם היה בא לפנינו\u0006\u0005]\u0006 אותו אדם \u0003וידעינן\u0004 \u0005[ויודעים היינו\u0006\u0005]\u0006 ש\u0003פלוני הואי\u0004 \u0005[הוא\u0006\u0005]\u0006 הרי \u0003הוי\u0004 \u0005[היה\u0006\u0005]\u0006 הנוזר \u0003נזיר, השתא נמי הוי\u0004 \u0005[עכשיו גם כן הריהו\u0006\u0005]\u0006 \u0003נזיר\u0004 מספק.","","","\u0003ראה\u0004 אדם \u0003את הכוי,\u0004 שהוא ספק חיה ספק בהמה, ויש בו דינים מיוחדים רבים, \u0003ואמר: \"הריני נזיר שזה חיה\",\u0004 ואדם אחר אמר: \u0003\"הריני נזיר שזה אינו חיה\",\u0004 ושלישי אמר: \u0003\"הריני נזיר שזה בהמה\",\u0004 ורביעי אמר: \u0003\"הריני נזיר שאין זה בהמה\",\u0004 וחמישי אמר: \u0003\"הריני נזיר שזה חיה ובהמה\",\u0004 ושישי אמר: \u0003\"הריני נזיר שאין זה לא חיה ולא בהמה\",\u0004 ואדם נוסף ששמע את כולם אמר \u0003\"הריני נזיר שאחד מכם נזיר\",\u0004 והוסיף אחר ואמר \u0003\"הריני נזיר שאין אחד מכם נזיר\",\u0004 ואדם נוסף אמר \u0003\"הריני נזיר שכולכם נזירין\" —\u0004 \u0003הרי כולן נזירין.\u0004","","ומביאים על האמור במשנתנו ש\"כולם נזירים\" \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא אחת\u0005]\u0006 שיש כאן בסך הכל \u0003תשעה נזירים, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא אחרת\u0005]:\u0006 \u0003תשע נזיריות.\u0004 ומבררים: \u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 ניתן להבין את הברייתא האומרת \u0003תשעה נזירין —\u0004 \u0003כגון דהוי גברי טפי דאתפיס ואזיל ביה\u0004 \u0005[שהיו אנשים מרובים שתפסו והלכו בו\u0006\u0005],\u0006 שהיו תשעה אנשים וכל אחד מהם נתפס בענין זה של הכוי ותלה בו את נזירותו.","\u0003אלא תשע נזיריות לחד גברא\u0004 \u0005[לאדם אחד\u0006\u0005]\u0006 \u0003היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה\u0006\u0005]?\u0006 \u0003בשלמא שית משכחת לה כדתנן\u0004 \u0005[נניח שש יכול אתה למצוא אותה כפי ששנינו\u0006 במשנה\u0005]\u0006 שהן שש האפשרויות שיכול אדם אחד לומר בצדדים שונים של ספק זה (שזה חיה, שזה אינו חיה, שזה בהמה, שזה אינו בהמה, שזה חיה ובהמה, שזה אינו חיה ואינו בהמה),","\u0003אבל תלת היכי משכחת לה\u0004 \u0005[שלש\u0006 נוספות איך אתה מוצא אותן\u0005],\u0006 שהרי רק אנשים אחרים יכולים לומר \"שאחד מכם נזיר\" \"שאין אחד מכם נזיר\"! \u0003אמר רב ששת: כגון\u0004 שעשו כך תשעה אנשים לפניו ו\u0003אמר \"הריני נזיר ונזירות הכל עלי\"\u0004 ולפי זה יכול אדם אחד לחייב עצמו בזה בתשע נזירויות.","","\u0003שלשה מינין\u0004 (סוגי דברים) \u0003אסורין בנזיר\u0004 מחמת נדר הנזירות: \u0003הטומאה\u0004 למת, \u0003והתגלחת\u0004 של שערו, \u0003ו\u0004אכילת ושתיית כל דבר מאכל ושתייה \u0003היוצא מן הגפן.\u0004 ובפרטי הדברים: \u0003וכל היוצא מן הגפן מצטרפין זה עם זה\u0004 לשיעור שמתחייבים מלקות על אכילתו. \u0003ואין חייב\u0004 מלקות \u0003עד שיאכל מן הענבים כזית.\u0004"],["\u0003משנה ראשונה אומרת:\u0004 אין הנזיר חייב מלקות \u0003עד שישתה רביעית יין. ר' עקיבא אומר: אפילו שרה פיתו ביין ויש בה כדי לצרף\u0004 עם היין בשיעור \u0003כזית —\u0004 \u0003חייב. ו\u0004עוד, הנזיר \u0003חייב\u0004 מלקות \u0003על היין בפני עצמו,\u0004 שהוא מפורש בתורה לאיסור, \u0003ועל הענבים בפני עצמן, ועל החרצנים בפני עצמן, ועל הזגים בפני עצמן,\u0004 שכל אחד מהם נאמר בו איסור מיוחד בתורה. \u0003ר' אלעזר בן עזריה אומר: אין חייב עד שיאכל\u0004 שיעור כזית שיש בו לפחות \u0003שני חרצנים וזג\u0004 אחד, כאמור בתורה באיסור אכילה של הנזיר \"מחרצנים (בלשון רבים) עד זג\" (במדבר ו, ד) ודנים עוד בביאור המילים:","\u0003אלו הן חרצנים ואלו הן זגים? החרצנים —\u0004 \u0003אלו החיצונים,\u0004 כלומר, קליפת העינב, \u0003הזגים\u0004 — \u0003אלו הפנימים\u0004 (הגרעינים), אלו \u0003דברי ר' יהודה. ר' יוסי אומר\u0004 ההיפך הוא הנכון, והסימן \u0003שלא תטעה: כזוג\u0004 (פעמון) \u0003של בהמה,\u0004 החלק \u0003החיצון\u0004 נקרא \u0003זוג,\u0004 וכמוהו זג של ענבים הוא קליפת הענב החיצונית, \u0003והפנימי\u0004 הדבר שמקשקש בתוך הפעמון נקרא \u0003עינבל,\u0004 וכמוהו בענב — הגרעינים.","שנינו במשנתנו, ש\u0003שלשה מינין אסורין בנזיר: הטומאה\u0004 והתגלחת והיוצא מן הגפן. ואפשר לדייק כך מלשון המשנה: \u0003היוצא מן הגפן —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005]\u0006 הוא האסור באכילת נזיר. ומכאן נלמד כי \u0003גפן עצמו\u0004 חלק אחר מעץ הגפן, שאינו מן הפירות — מותר. ומעירים: אם כן \u0003מתניתין\u0004 \u0005[משנתנו\u0006\u0005]\u0006 היא ש\u0003לא\u0004 כשיטת \u0003ר' אלעזר. דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: אפילו עלין\u0004 של גפן \u0003ולולבין\u0004 (ענפים רכים) \u0003במשמע\u0004 של האיסור לנזיר.","\u0003איכא דאמרי לה אסיפא\u0004 \u0005[יש שאמרו אותה,\u0006 את ההערה הזו, על סופה\u0005]\u0006 של המשנה, ששנינו בה: \u0003אינו חייב אלא עד שיאכל מן הענבים כזית.\u0004 ונדייק מכאן: \u0003מן הענבים —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 \u0003מהגפן עצמו —\u0004 \u0003לא.\u0004 אם כן \u0003מתניתין\u0004 \u0005[משנתנו\u0006\u0005]\u0006 היא ש\u0003לא\u0004 כשיטת \u0003ר' אלעזר, דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' אלעזר אומר: אפילו עלין ולולבין במשמע.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 הם חלוקים\u0005],\u0006 מהו בסיס מחלוקתם? ומסבירים: \u0003ר' אלעזר דריש\u0004 \u0005[דורש\u0006\u0005]\u0006 את הכתובים בשיטת מדרש הלכה של \u0003ריבויי ומיעוטי\u0004 \u0005[ריבויים ומיעוטים\u0006\u0005]\u0006 ואילו \u0003רבנן דרשי כללי ופרטי\u0004 \u0005[חכמים דורשים\u0006 את הכתובים בשיטת כללים ופרטים\u0005].\u0006 ומפרטים: \u0003ר' אלעזר דריש רבויי ומיעוטי\u0004 \u0005[דורש ריבויים ומיעוטים\u0006\u0005],\u0006 וכך הוא דורש: מה שנאמר \u0003\"מיין ושכר יזיר\"\u0004 (במדבר ו, ג) — הרי \u0003מיעט\u0004 הכתוב ואמר שהאיסור הוא רק ביין ושיכר, ונאמר \u0003\"מכל אשר יעשה מגפן היין\"\u0004 (במדבר ו, ד) — ובכך \u0003ריבה\u0004 הכתוב, הרי לנו בכתובים","\u0003מיעט וריבה,\u0004 ולפי כללי המדרש: \u0003ריבה הכל.\u0004 אם כן \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 \u0003ריבה —\u0004 \u0003ריבה\u0004 את \u0003כל מילי\u0004 \u0005[הדברים\u0006\u0005]\u0006 היוצאים מן הגפן, \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 \u0003מיעט?\u0004 שהרי בכל זאת יש מיעוט בכתוב. לשיטה זו המיעוט בא למעט רק דבר אחד! — \u0003מיעט שבישתא\u0004 \u0005[זמורות\u0006\u0005]\u0006 של הגפן, שאם אכל מהן לא עבר.","\u0003ו\u0004אילו \u0003רבנן דרשי כללי ופרטי\u0004 \u0005[חכמים דורשים כללים ופרטים\u0006\u0005],\u0006 וכך הם דורשים: נאמר \u0003\"מיין ושכר יזיר\"\u0004 — הרי זה \u0003פרט,\u0004 וכן נאמר \u0003\"מכל אשר יעשה מגפן היין\"\u0004 — הרי זה \u0003כלל,\u0004 \u0003\"מחרצנים ועד זג\" —\u0004 \u0003חזר ופרט,\u0004 אם כן יש לנו \u0003פרט וכלל ופרט,\u0004 ולפי שיטה זו \u0003אי\u0004 \u0005[אין\u0006\u0005]\u0006 \u0003אתה דן,\u0004 למד, לרבות \u0003אלא\u0004 לדברים אחרים שהם \u0003כעין\u0004 כמו \u0003הפרט: מה הפרט\u0004 ה\u0003מפורש\u0004 בכתוב הוא \u0003פרי\u0004 או \u0003פסולת פרי\u0004 (חרצנים וזגים) — \u0003אף כל\u0004 מה שנאסר מריבוי הכלל הכתוב הוא \u0003פרי ופסולת פרי\u0004 (אבל לא עלים ולולבים, כפי שסבור ר' אלעזר).","ויש לשאול על כך: \u0003אי\u0004 \u0005[אם\u0006 כן\u0005]\u0006 שמא נאמר: \u0003מה הפרט מפורש\u0004 שהוא \u0003פרי גמור —\u0004 \u0003אף כל פרי גמור,\u0004 ולפי זה אף פרי בוסר אינו בכלל האיסור. \u0003אמרת\u0004 (אומר אתה) כנגד זה: \u0003אם כן מה הניח לך הכתוב במשמעו שלא אמרו\u0004 שתצטרך ללומדו מדרשת הכתוב? \u0003ענבים לחים ויבשים —\u0004 \u0003הא כתיבי\u0004 \u0005[הרי\u0006 הם כתובים\u0005]\u0006 במפורש, \u0003יין וחומץ\u0004 — \u0003הא כתיבי\u0004 \u0005[הרי\u0006 הם כתובים\u0005],\u0006 ואם כן מה באה לשון הכלל בכתוב להוסיף? \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003אין עליך לדון כלשון אחרון\u0004 שפרי בוסר אינו בכלל, \u0003אלא כלשון ראשון\u0004 שפרי בוסר בכלל.","ויש לשאול: \u0003ומאחר שסופינו לרבות כל דבר\u0004 שהוא מעין הפרט, פרי ופסולת פרי, \u0003מה תלמוד לומר\u0004 לאחר הכלל \u0003\"מחרצנים ועד זג\"?\u0004 הרי זה בא \u0003לומר לך\u0004 כלל במדרש ההלכה בכל התורה: \u0003כל מקום שאתה מוצא פרט וכלל\u0004 בלבד — \u0003אי\u0004 \u0005[אין\u0006\u0005]\u0006 \u0003אתה רשאי למשכו\u0004 (להרחיבו) \u0003ולדונו כעין הפרט\u0004 ולומר שהכלל הוא רק הרחבה והכללה של פרטים קודמים,","\u0003אלא נעשה כלל מוסף על הפרט\u0004 וכולל בתוכו כל דבר (אף שאינו מעין הפרט), \u0003עד שיפרוט לך הכתוב\u0004 ויוסיף פרט לאחר הכלל, \u0003כדרך שפרט לך בנזיר,\u0004 שהוסיף לאחר \"מכל אשר ייעשה\" — \"מחרצנים ועד זג\", ואז למדים במדת הדרשה של פרט וכלל ופרט, שאף ההכללה באה להוסיף רק מעין הפרט, וכפי שלמדנו אצלנו שאין עלים ולולבים בכלל זה. ומעתה דנים בפרטי מדרש זה.","\u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]:\u0006 \u0003מה הפרט מפורש\u0004 בכתוב שהוא \u0003פרי ופסולת פרי —\u0004 \u0003אף כל פרי ופסולת פרי\u0004 אסור לנזיר. ומסבירים: \u0003פרי\u0004 המפורש בכתוב הוא \u0003עינבי\u0004 \u0005[ענבים\u0006\u0005],\u0006 \u0003פסולת פרי\u0004 המפורשת בכתוב \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 \u0003היא —\u0004 \u0003חומץ\u0004 (\"חומץ יין וחומץ שכר לא ישתה\". במדבר ו׳:ג׳).","\u0003\"אף כל פרי\"\u0004 שמוסיף מדרש זה \u0003מאי היא\u0004 \u0005[מה הוא\u0006\u0005] —\u0006 \u0003גוהרקי\u0004 \u0005[בוסר,\u0006 ענבים שלא הגיעו לכלל בישולם\u0005].\u0006 ויש לשאול: \u0003\"אף כל\"\u0004 שהוסיף לגבי \u0003פסולת פרי, מאי\u0004 \u0005[מה\u0006\u0005]\u0006 \u0003היא\u0004 איזו פסולת פרי בא להוסיף על מה שמפורש בכתוב? \u0003אמר רב כהנא: לאיתויי עינבי דכרין\u0004 \u0005[להביא,\u0006 להוסיף, ענבים שהתליעו\u0005].\u0006 ועל מה שנאמר \u0003\"\u0004מחרצנים \u0003ועד זג\", אמר רבינא:\u0004 לשון זו באה \u0003לאיתויי\u0004 \u0005[להביא\u0006\u0005]\u0006 את חלק הפרי שהוא \u0003בין הבינים\u0004 שנמצא בין החרצנים והזג.","וממשיכים לדון בפרטי הברייתא, \u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]\u0006 בברייתא: \u0005[אי\u0006 \u0005[אם\u0006\u0005]\u0006 \u0005]\u0006 \u0003מה הפרט מפורש פרי גמור אף כל פרי גמור —\u0004 \u0003אמרת: אם כן מה הניח הכתוב במשמעו שלא אמרו? ענבים לחים ויבשים —\u0004 \u0003הא כתיבי\u0004 \u0005[הרי\u0006 הם כתובים\u0005],\u0006 \u0003יין וחומץ —\u0004 \u0003הא כתיבי\u0004 \u0005[הרי\u0006 הם כתובים\u0005],\u0006 \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003אין עליך לדון כלשון אחרון אלא כלשון ראשון. ומאחר שסופינו לרבות כל דבר, מה תלמוד לומר \"מחרצנים ועד זג\" —\u0004 \u0003לומר לך: כל מקום שאתה מוצא פרט וכלל אי\u0004 \u0005[אין\u0006\u0005]\u0006 \u0003אתה רשאי למושכו לדונו כעין הפרט\u0004 דווקא, \u0003אלא נעשה כלל מוסף על הפרט\u0004 ומוסיף אף דברים שאינם כעין הפרט, \u0003עד שיפרוט לך הכתוב\u0004"],["\u0003כדרך שפרט לך בנזיר \"מחרצנים ועד זג\".\u0004 ושואלים: \u0003ול\u0004דעת \u0003ר' אלעזר בן עזריה דקא מוקים להאי\u0004 \u0005[שמעמיד,\u0006 מסביר את הכתוב הזה\u0005]\u0006 \u0003\"מחרצנים ועד זג\"\u0004 (במדבר ו, ד) באופן שבא \u0003לומר שאינו חייב עד שיאכל שני חרצנים וזג,\u0004 אם כן \u0003פרטא מנא ליה\u0004 \u0005[הפרט מניין לו\u0006\u0005],\u0006 מניין יודע הוא את שיטת הלימוד הזו של פרט וכלל ופרט, שהרי לשיטתו אין בכתוב זה פרט שבא לצמצם את הכלל אלא דין בפני עצמו! ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא\u0006\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' אלעזר דדריש\u0004 \u0005[שדורש\u0006\u0005]\u0006 כאן בדרך הלימוד של \u0003מיעט וריבה.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005]\u0006 שהוא דורש \u0003כ\u0004דעת \u0003רבנן\u0004 \u0005[כחכמים\u0006\u0005],\u0006 ואף הוא סבור שיש כאן פרט וכלל ופרט, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006\u0005]\u0006 שאין משמעות הכתוב אלא רק \u0003כדאמר\u0004 \u0005[כמו שאומר\u0006\u0005]\u0006 \u0003ר' אלעזר בן עזריה,\u0004 אם כן \u0003ליכתביה רחמנא להאי\u0004 \u0005[שתכתוב התורה את\u0006 הביטוי הזה\u0005]\u0006 \u0003\"מחרצנים ועד זג\" גבי פרטי\u0004 \u0005[אצל,\u0006 יחד עם הפרטים\u0005]\u0006 יין חומץ וכו', \u0003למאי הלכתא כתביה בתר\u0004 \u0005[למה,\u0006 לאיזו הלכה כתב אותו אחר\u0005]\u0006 ה\u0003כלל?\u0004 \u0003שמע מינה למידייניה\u0004 \u0005[למד מכאן\u0006 שנכתב כך כדי לדונו\u0005]\u0006 \u0003בכלל ופרט.\u0004","ושואלים: אם כן \u0003ואימא כוליה להכי\u0004 \u0005[ואמור ש\u0006כל המקרא כולו לשם כך\u0005]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא\u0006\u0005]\u0006 רק לשם הכלל והפרט, ואין ללמוד ממנו כפי שלמד ר' אלעזר בן עזריה! ומשיבים לשיטתו: \u0003אם כן לכתוב\u0004 \u0005[שתכתוב\u0006 התורה\u0005]\u0006 \u0003או שני חרצנים או שני זגים\u0004 שניהם בלשון רבים, \u0003או חרצן וזג\u0004 שניהם בלשון יחיד, \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו הלכה\u0005]\u0006 \u0003כתב רחמנא\u0004 \u0005[כתבה תורה\u0006\u0005]\u0006 \u0003\"מחרצנים ועד זג\" —\u0004 \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 \u0003למידרש ביה\u0004 \u0005[לדרוש בו\u0006\u0005]\u0006 \u0003כלל ופרט, ואיכא נמי למידרש ביה\u0004 \u0005[ויש גם כן לדרוש בו\u0006\u0005]:\u0006 \u0003עד שיאכל שני חרצנים וזג.\u0004","ושואלים: \u0003ור' אלעזר דדריש\u0004 \u0005[שדורש\u0006\u0005]\u0006 משיטת הלימוד של \u0003מיעט וריבה,\u0004 ולמד כי אף לולבים ועלי הגפן בכלל האיסור, אם כן דרך מדרש ההלכה של \u0003פרט וכלל ופרט מנא ליה\u0004 \u0005[מנין לו\u0006\u0005]?\u0006","\u0003אמר ר' אבהו: נפקא\u0004 \u0003ליה מהאי קרא\u0004 \u0005[יוצא לו,\u0006 נלמד לו הדבר, מפסוק זה\u0005]\u0006 שנאמר בפרשת השומרים: \u0003\"כי יתן איש אל רעהו חמור או שור או שה\u0004וכל בהמה לשמור ומת וכו'... שבועת ה' תהיה בין שניהם\u0003\"\u0004 (שמות כב, ט) — \"חמור או שור או שה\" הרי זה \u0003פרט, \"וכל בהמה\" —\u0004 \u0003כלל,\u0004 כל בהמות, \u0003\"לשמר\" —\u0004 \u0003חזר ופרט,\u0004 הרי לפנינו בכתוב \u0003פרט וכלל ופרט,\u0004 ובמקרה כזה \u0003אי\u0004 \u0005[אין\u0006\u0005]\u0006 \u0003אתה דן\u0004 להוסיף דברים על האמור במפורש בכתוב \u0003אלא\u0004 רק אלו שהם \u0003כעין הפרט,\u0004 ואינו כולל אלא דברים הניתנים לשמירה.","\u0003רבא אמר: נפקא ליה\u0004 \u0005[יוצא לו\u0006\u0005]\u0006 לר' אלעזר הלימוד \u0003מהאי קרא\u0004 \u0005[מפסוק זה\u0006\u0005],\u0006 שנאמר: \u0003\"ואם מן\u0004 הצאן קרבנו מן הכשבים או מן העזים לעולה זכר תמים יקריבנו\u0003\"\u0004 (ויקרא א, י), ובדרך זו: \"ואם מן\" — הרי זה \u0003פרט,\u0004 ש\"מן\" הוא פירוט, ומשמעו חלק מן הדברים ולא כולם. \u0003\"הצאן\"\u0004 — הוא \u0003כלל,\u0004 ובכלל זה אף בהמות שנעשתה בהם עבירה, \u0003\"כבשים ועזים\" —\u0004 \u0003חזר ופרט,\u0004 הרי כאן","\u0003פרט וכלל ופרט,\u0004 ובמקרה כזה \u0003אי\u0004 \u0005[אין\u0006\u0005]\u0006 \u0003אתה דן אלא כעין הפרט\u0004 ואינך מרחיב את הכלל לכל צאן, אלא רק לאלה שלא נעשתה עבירה בגופם (כגון שעשה אותה עבודה זרה, או שחרש בה בשבת).","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב יהודה מדיסקרתא לרבא: ולילף\u0004 \u0005[ושילמד\u0006\u0005]\u0006 ר' אלעזר \u0003מן הדין קרא\u0004 \u0005[הפסוק הזה\u0006\u0005]\u0006 שהוא פסוק קודם באותה פרשה \u0003\"מן\u0004 הבהמה מן הבקר ומן הצאן תקריבו את קרבנכם\u0003\"\u0004 (ויקרא א, ב), ובאופן כזה: \"מן\" — הרי זה \u0003פרט\u0004 למעט חיה, \u0003\"הבהמה\" —\u0004 \u0003כלל\u0004 ואף חיה בכלל זה (ראה דברים פרק יד), \u0003\"בקר וצאן\" —\u0004 \u0003חזר ופרט,\u0004 ו\u0003פרט וכלל ופרט אי\u0004 \u0005[אין\u0006\u0005]\u0006 \u0003אתה דן אלא כעין הפרט\u0004 ואינך לומד לרבות כל הקרוי בהמה (ואפילו חיות) אלא מה שהוא בגדר בהמה ממש.","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003מן האי ליכא למשמע מינה\u0004 \u0005[מ\u0006כתוב זה אין ללמוד ממנו\u0005],\u0006 \u0003דאי מהתם, הוה אמינא\u0004 \u0005[שאם משם, הייתי אומר\u0006\u0005]\u0006 ומפרש באופן אחר: \u0003\"הבהמה\"\u0004"],["\u0003חיה בכלל בהמה\u0004 ולא היינו ממעטים חיה בדרשה זו, שהרי חיה אינה עולה לקרבן, ונמצא שאין ללמוד שם בדרך זו.","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 איך אפשר לפרש \u0003חיה בכלל בהמה\u0004 בפסוק זה? \u0003הא כתיב\u0004 \u0005[הרי נאמר\u0006\u0005]\u0006 \u0003\"בקר וצאן\", והוה ליה\u0004 \u0005[והרי זה\u0006\u0005]\u0006 \u0003פרט\u0004 \"מן\" \u0003וכלל\u0004 \"בהמה\" ופרט \"בקר וצאן\", \u0003ואי\u0004 \u0005[ואין\u0006\u0005]\u0006 \u0003אתה דן אלא כעין הפרט\u0004 האחרון המפורש, דהיינו בקר וצאן, ולא חיה!","ולעצם הלימוד במידות כללים ופרטים לכעין הפרט, שואלים: \u0003ומנלן דהכי\u0004 \u0005[ומניין לנו שכך\u0006\u0005]\u0006 \u0003הוא? דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005]:\u0006 נאמר בקשר להעלאת מעות מעשר שני לירושלים","\u0003\"ונתתה הכסף בכל אשר תאוה נפשך\u0004 בבקר ובצאן וביין ובשכר ובכל אשר תשאלך נפשך\u0003\"\u0004 (דברים יד, כו) — \"בכל אשר תאוה נפשך\" — הרי זה \u0003כלל, \"בבקר ובצאן וביין ובשכר\" —\u0004 \u0003פרט, \"ובכל אשר תשאלך נפשך\" —\u0004 \u0003חזר וכלל.\u0004","\u0003כלל ופרט וכלל אי\u0004 \u0005[אין\u0006\u0005]\u0006 \u0003אתה דן אלא כעין הפרט; מה הפרט מפורש\u0004 הוא \u0003פרי מפרי,\u0004 דבר הפרה ורבה שמוליד וולדות מתוכו, \u0003וגידולי קרקע\u0004 שמקור גידולם ופרנסתם הוא מן האדמה, \u0003אף כל\u0004 שקונים בכסף מעשר צריך להיות \u0003פרי מפרי וגידולי קרקע,\u0004 כגון עופות (ולא דגים, ולא מים או מלח שאינם כלולים בהגדרה זו).","ומבררים סדרת שאלות כלליות בבירור דרכי מדרש ההלכה. \u0003מכדי\u0004 \u0005[הלוא\u0006\u0005]\u0006 \u0003כלל ופרט וכלל —\u0004 \u0003כעין פרטא דיינינן\u0004 \u0005[הפרט אנו דנים\u0006\u0005],\u0006 אם כן \u0003כללא בתרא מאי אהני\u0004 \u0005[הכלל האחרון\u0006 שבכתוב, מה הועיל\u0005]?\u0006 והרי אפשר היה להגיע לאותה מסקנה גם על ידי כלל ופרט בלבד! ומשיבים: \u0003אהני לאוסופי\u0004 \u0005[הועיל\u0006 הכלל האחרון להוסיף\u0005]\u0006 את \u0003כל דדמי ליה\u0004 \u0005[הדומה לו\u0006\u0005]\u0006 גם אם אינו נמנה במפורש בין הפרטים.","\u0003ותו\u0004 \u0005[ועוד\u0006\u0005]\u0006 שואלים: \u0003פרט וכלל ופרט —\u0004 \u0003כעין הפרט דיינינן\u0004 \u0005[אנו דנים\u0006\u0005],\u0006 אם כן \u0003פרטא בתראה מאי אהני\u0004 \u0005[הפרט האחרון מה הועיל\u0006\u0005],\u0006 די היה ללמוד אותו לימוד אם היה רק פרט וכלל! ומשיבים: \u0003אי לאו פרטא בתראה\u0004 \u0005[אם לא\u0006 היה כתוב הפרט האחרון\u0005],\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]:\u0006 \u0003נעשה כלל מוסף על הפרט\u0004 ונרחיב את הפרט בכל הדרכים האפשרויות, ולכן בא הפרט האחרון לצמצם את ההכללה, רק לדבר שהוא מעין הפרט.","ועוד שואלים: \u0003ומכדי\u0004 \u0005[והרי\u0006\u0005]\u0006 \u0003תרין כללי ופרטא\u0004 \u0005[שני כללים ופרט\u0006\u0005] —\u0006 מידת \"כלל ופרט וכלל\" \u0003ו\u0004גם \u0003תרין פרטי וכללא\u0004 \u0005[שני פרטים וכלל\u0006\u0005] —\u0006 מידת \"פרט וכלל ופרט\" \u0003(כללא)\u0004 הלוא בשניהם \u0003כעין פרטא דיינינן\u0004 \u0005[כעין הפרט אנו דנים\u0006\u0005],\u0006 אם כן \u0003מאי איכא ביני וביני\u0004 \u0005[מה יש בין\u0006 אלו ובין אלו\u0005]?\u0006 שלכאורה מידות אלה זהות זו לזו!","ומשיבים: \u0003איכא\u0004 \u0005[יש\u0006\u0005]\u0006 הבדל; ש\u0003אילו תרתין כללי ופרטא\u0004 \u0005[שני כללים ופרט\u0006\u0005],\u0006 \u0003אי איכא פרטא דדמי ליה\u0004 \u0005[אם יש פרט\u0006 נוסף שדומה לו\u0005]\u0006 לפרט המפורש בכתוב \u0003אפילו בחד צד מרבינן\u0004 \u0005[בצד אחד מרבים אנו\u0006\u0005]\u0006 אותו, משום שיש בכתוב שתי הכללות, ואילו ב\u0003תרי פרטי וכללא\u0004 \u0005[שני פרטים וכלל\u0006\u0005]\u0006 \u0003אי איכא פרטא דדמי\u0004 \u0005[אם יש פרט\u0006 נוסף שדומה\u0005]\u0006 לפרט המפורש בכתוב \u0003משני צדדין —\u0004 \u0003מרבינן\u0004 \u0005[מרבים אנו\u0006 אותו\u0005],\u0006 אבל אם דומה \u0003בחד צד\u0004 \u0005[בצד אחד\u0006\u0005] —\u0006 \u0003לא מרבינן\u0004 \u0005[אין אנו מרבים\u0006\u0005],\u0006 משום שיש בכתוב שני פרטים הבאים לצמצמו.","ועוד שואלים: \u0003מכדי\u0004 \u0005[הלא\u0006\u0005]\u0006 בדרך הלימוד של \u0003פרט וכלל —\u0004 \u0003נעשה כלל מוסף על הפרט, ואיתרבי\u0004 \u0005[והתרבו\u0006\u0005]\u0006 \u0003כל מילי\u0004 \u0005[הדברים\u0006\u0005]\u0006 על ידי הכלל, \u0003ו\u0004כן בדרך הלימוד של \u0003מיעט וריבה נמי\u0004 \u0005[גם כן\u0006\u0005] —\u0006 \u0003ריבה הכל, ואיתרבי\u0004 \u0005[והתרבו\u0006\u0005]\u0006 \u0003כל מילי\u0004 \u0005[הדברים\u0006\u0005],\u0006 אם כן \u0003מאי איכא\u0004 \u0005[מה יש,\u0006 מה ההבדל\u0005]\u0006 \u0003בין\u0004 שיטת לימוד של \u0003מיעט וריבה, ל\u0004בין שיטת הלימוד של \u0003פרט וכלל?\u0004","ומשיבים: \u0003איכא\u0004 \u0005[יש\u0006 הבדל\u0005]\u0006 ש\u0003אילו\u0004 במידת \u0003פרט וכלל מרבינן\u0004 \u0005[מרבים אנו\u0006\u0005]\u0006 לענין נזיר \u0003אפילו עלין ולולבין\u0004 של עץ הגפן שהם אסורים לנזיר. \u0003ו\u0004אילו לשיטת \u0003מיעט וריבה\u0004 אנו מרבים פחות, ולכן \u0003לולבין —\u0004 \u0003אין\u0004 \u0005[כן\u0006\u0005],\u0006 אבל \u0003עלין —\u0004 \u0003לא.\u0004","\u0003אמר ר' אבהו אמר ר' יוחנן: כל איסורין שבתורה אין היתר מצטרף לאיסור,\u0004 שגם אם הם מעורבים יחד, אין ההיתר מצטרף להשלים לשיעור של איסור, \u0003חוץ מאיסורי נזיר,\u0004 שהאוכל חצי זית של איסור וחצי זית של היתר הריהם מצטרפים לכזית שהוא שיעור אכילה — ולוקה. ומדוע? \u0003שהרי אמרה תורה:\u0004 \"וכל \u0003משרת\u0004 ענבים לא ישתה\" (במדבר ו, ג) כלומר, לרבות אפילו דבר אחר שהוא של היתר ששרו בו מה שנעשה מן הענבים."],["\u0003זעירי אמר: אף שאור\u0004 שעובר עליו משום \u0003בל תקטירו\u0004 (\"כי כל שאור וכל דבש לא תקטירו ממנו אשה לה'\". ויקרא ב, יא) ישנו אותו דין של היתר המצטרף לאיסור, שלא רק על הקטרת השאור בכזית עוברים, אלא גם על המקטיר עיסה שיש בה תערובת של שאור ודבר מותר ששיעורם ביחד כזית. ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת מי היא\u0005]\u0006 הלכה זו של זעירי — \u0003כ\u0004דעת \u0003ר' אלעזר, דדריש\u0004 \u0005[שדורש\u0006\u0005]\u0006 \u0003\"כל\"\u0004 (\"כל מחמצת לא תאכלו\". שמות יב, כ) לרבות תערובתו?","\u0003אי הכי\u0004 \u0005[אם כך\u0006\u0005]\u0006 \u0003לענין חמץ נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 כיון שנאמר בו \"כל מחמצת לא תאכלו\" יאמר זעירי שיש איסור לא רק על אכילת כזית ממנו, אלא אף על כזית מתערובת שיש בה חמץ! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כך הוא גם כן\u0006\u0005]\u0006 שזעירי סבור שאף בחמץ היתר מצטרף לאיסור. \u0003אלא\u0004 מה שאמר זעירי בשאור דווקא היה זה \u0003לאפוקי\u0004 \u0005[להוציא\u0006\u0005]\u0006 \u0003מ\u0004דברי \u0003אביי\u0004 ש\u0003אמר: יש הקטרה בפחות מכזית\u0004 וחייבים עליה אם מקטיר שאור, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 זעירי ש\u0003אין הקטרה בפחות מכזית,\u0004 ורק אם היה שיעור כזית של שאור (או של שאור ודבר אחר המצטרף אליו) חייבים על הקטרת תערובת זו.","מסופר: \u0003יתיב\u0004 \u0005[ישב\u0006\u0005]\u0006 \u0003רב דימי וקאמר\u0004 \u0005[ואמר\u0006\u0005]\u0006 \u0003לה להא שמעתא\u0004 \u0005[את ההלכה הזו\u0006\u0005]\u0006 של ר' אבהו, בשמו של ר' יוחנן, שבכל איסורים שבתורה (חוץ מנזיר) אין היתר מצטרף לאיסור. \u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003המקפה\u0004 (תבשיל סמיך) \u0003של\u0004 פירות \u0003תרומה, והשום והשמן\u0004 שבה היו \u0003של חולין, ונגע טבול יום\u0004 (טמא ביום שטבל מטומאתו, שפוסל תרומה במגע) \u0003במקצתן —\u0004 \u0003פסל את כולן\u0004 בגלל התרומה שהיא עיקר המקפה. ואם היה להיפך, שהיתה \u0003מקפה של חולין והשום והשמן של תרומה, ונגע טבול יום במקצתן —\u0004 \u0003לא פסל אלא מקום מגעו.\u0004","\u0003והוינן\u0004 \u0005[והיינו עוסקים\u0006\u0005]\u0006 ומתקשים \u0003בה\u0004 בהלכה זו: \u0003מקום מגעו\u0004 עצמו \u0003אמאי\u0004 \u0005[מדוע\u0006\u0005]\u0006 \u0003פסול?\u0004 הרי מה שנגע בו היה רובו חולין, וחולין אינם נפסלים במגע טבול יום! \u0003ואמר רבה בר בר חנה אמר ר' יוחנן: מה טעם —\u0004 \u0003הואיל וזר\u0004 האוכל תערובת זו \u0003לוקה עליה בכזית,\u0004 לכך מחשיבים את הכל כאילו היה זה תרומה.","ומסכם אביי את שאלתו: \u0003מאי טעמיה\u0004 \u0005[מה טעמו\u0006\u0005]\u0006 של ר' יוחנן שלוקה על התערובת?"],["\u0003לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006 \u0003משום\u0004 ש\u0003היתר מצטרף לאיסור,\u0004 ומשום כך חייב האוכל כזית ממקפה זו? ואם כן לא רק בנזיר, אלא אף בשאר איסורים שבתורה היתר מצטרף לאיסור! \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 רב דימי: \u0003לא, מאי\u0004 \u0005[מה\u0006\u0005]\u0006 פירוש \u0003\"כזית\"\u0004 שאמרו — \u0003דאיכא\u0004 \u0005[שיש\u0006\u0005]\u0006 כדי שיעור \u0003כזית בכדי אכילת פרס,\u0004 שתוך כדי זמן אכילה של פרס (חצי ככר לחם) יש בתערובת שהוא אוכל כזית מן התרומה, ומשום כך הזר האוכלו חייב.","ושאל אביי: \u0003ו\u0004כי \u0003אכילת פרס דאורייתא\u0004 \u0005[מן התורה\u0006\u0005]\u0006 \u0003היא?\u0004 כשאדם אוכל כזית של איסור בתוך אכילת פרס האם חייבים עליו ממש מדין תורה, שאמר רבה בר בר חנה שלוקים עליו? \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003אין\u0004 \u0005[כך\u0006\u0005].\u0006 שאל אותו אביי: \u0003אי הכי, אמאי פליגי רבנן עליה\u0004 \u0005[אם כך, מדוע חולקים חכמים עליו\u0006\u0005]\u0006 על \u0003ר' אלעזר בכותח הבבלי,\u0004 שהוא מין תבלין שיש בו תערובת חמץ, וחכמים אומרים שאיננו חייב עליו משום חמץ בפסח?","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003הנח לכותח הבבלי, דליכא\u0004 \u0005[שאין בו\u0006\u0005]\u0006 שיעור \u0003כזית\u0004 חמץ הנאכל \u0003ב\u0004שיעור זמן של \u0003כדי אכילת פרס,\u0004 ומדוע? \u0003אי דקא שריף ליה מישרף\u0004 \u0005[אם שהוא גומע אותו\u0006\u0005]\u0006 את הכותח בבת אחת — אין זו נחשבת אכילה, כיון ש\u0003בטלה דעתו אצל כל אדם,\u0004 שאין אדם רגיל שותה בבת אחת תבלין חריף זה. \u0003אי מישטר קא שטר\u0004 \u0005[אם מתבל הוא בו\u0006\u0005]\u0006 הרי שוב \u0003לא משכחת\u0004 \u0005[אין אתה מוצא\u0006\u0005]\u0006 באכילתו שיעור אכילה של \u0003כזית ב\u0004שיעור זמן של \u0003כדי אכילת פרס,\u0004 שהדבר לוקח יותר זמן.","\u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 אביי ממה ששנינו: היו לפניו \u0003שתי מדוכות\u0004 של תבלין, \u0003אחת של תרומה ואחת של חולין\u0004 ובכל אחת מהן תבלינים. \u0003ו\u0004היו \u0003לפניו שתי קדירות אחת של\u0004 תבשילי \u0003תרומה ואחת של חולין, ונפלו אלו\u0004 התבלינים \u0003לתוך אלו\u0004 הקדירות, ואין אנו יודעים אלו תבלינים נפלו בקדירות — \u0003שתיהן מותרות\u0004 באכילה, וזו של החולין נאכלת אף על ידי ישראל, \u0003שאני אומר:\u0004 תבליני \u0003חולין לתוך\u0004 תבשיל \u0003חולין נפלו, ותרומה לתוך תרומה נפלה.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר שמי שאוכל \u0003כזית בכדי אכילת פרס\u0004 חייב מ\u0003דאורייתא\u0004 \u0005[מן התורה\u0006\u0005],\u0006 \u0003אמאי אמרינן\u0004 \u0005[מדוע אנו אומרים\u0006\u0005]\u0006 את הנימוק של \u0003\"שאני אומר\"\u0004 ומתירים? והרי יתכן שהיתה תרומה בתוך חולין, וכשאוכל אכילת פרס יש להניח שיש שם כזית של תרומה ואסור!","אמר לו רב דימי: \u0003אלא מאי\u0004 \u0005[מה\u0006\u0005]\u0006 תאמר, שטעם הדבר משום ש\u0003היתר מצטרף לאיסור?\u0004 אם כן עדיין נשארת אותה השאלה במקומה: \u0003אמאי אמרינן\u0004 \u0005[מדוע אנו אומרים\u0006\u0005]\u0006 \u0003\"שאני אומר\"?\u0004 והרי גם כאן אפשר להקשות: והרי ההיתר מצטרף לאיסור! \u0003אלא הנח לתרומת תבלין\u0004 ש\u0003דרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005]\u0006 \u0003היא\u0004 מעיקרה, וכיון שהיא מדברי סופרים אנו מקילים בכך ומניחים הנחה זו של \"שאני אומר\".","\u0003איתיביה\u0004 \u0005[הקשה לו\u0006\u0005]\u0006 אביי ממקום אחר, ששנינו: \u0003שתי קופות\u0004 (סלים) של תבואה, \u0003אחת של תרומה ואחת של חולין, ולפניהן שתי סאין\u0004 של תבואה \u0003אחת\u0004 מהן \u0003של חולין ואחת של תרומה, ונפלו אלו לתוך אלו —\u0004 \u0003שניהן מותרין, שאני אומר: חולין לתוך חולין נפלו, תרומה לתוך תרומה נפלה.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר שלאכול \u0003כזית בכדי אכילת פרס אסור\u0004 מן התורה, \u0003אמאי אמרינן\u0004 \u0005[מדוע אנו אומרים\u0006\u0005]\u0006 \u0003\"שאני אומר\"?\u0004"],["\u0003בשלמא לדידי\u0004 \u0005[נניח לשיטתי\u0006\u0005]\u0006 \u0003דאמינא\u0004 \u0005[שאני אומר\u0006\u0005]\u0006 \u0003משום\u0004 ש\u0003היתר מצטרף לאיסור,\u0004 אני מסביר זאת שמדובר במקרה \u0003כגון דנפישי\u0004 \u0005[שמרובים\u0006\u0005]\u0006 ה\u0003חולין\u0004 על התרומה, שכיון שההיתר מרובה, אין לומר שהוא מצטרף לאיסור. \u0003אלא לדידך\u0004 \u0005[לשיטתך\u0006\u0005]\u0006 \u0003דאמרת\u0004 \u0005[שאתה אומר\u0006\u0005]\u0006 שהטעם הוא \u0003משום דאיכא\u0004 \u0005[שיש\u0006\u0005]\u0006 \u0003כזית בכדי אכילת פרס\u0004 — אפילו \u0003כי נפישי\u0004 \u0005[כאשר מרובים\u0006\u0005]\u0006 ה\u0003חולין מאי הוי\u0004 \u0005[מה יש\u0006 בכך\u0005]?\u0006 הרי בכל אופן יש שם כזית תרומה בכדי אכילת פרס!","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 \u0003הנח לתרומה בזמן הזה,\u0004 שכל עיקרה הוא מ\u0003דרבנן\u0004 \u0005[מדברי סופרים\u0006\u0005],\u0006 ואין מחמירים בה בזמן שאין שם איסור אלא בכדי אכילת פרס.","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003אביי: ממאי דהאי\u0004 \u0005[ממה\u0006 מניין אתה יודע שזה\u0005]\u0006 הכתוב \"וכל \u0003משרת\u0004 ענבים לא ישתה\" (במדבר ו, ג) \u0003ל\u0004למד ענין \u0003היתר מצטרף לאיסור הוא דאתא\u0004 \u0005[שבא\u0006\u0005]\u0006 וכפי שהבאת בשם ר' יוחנן (לעיל נזיר לה, ב)? \u0003דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 לענין \u0003ליתן טעם כעיקר הוא דאתא\u0004 \u0005[שבא\u0006\u0005],\u0006 לומר שטעמו של איסור נחשב כגוף האיסור!","על שאלתו זו של אביי תוהים: \u0003ולאביי, מעיקרא קא קשיא ליה מאי דקאמר\u0004 \u0005[מתחילה היה קשה לו מה שאומר\u0006\u0005]\u0006 \u0003רב דימי\u0004 בשם ר' יוחנן שבכל איסורי התורה אין היתר מצטרף לאיסור חוץ מאשר באיסורי נזיר שנאמר בהם \"משרת\", \u0003וקא מותיב ליה\u0004 \u0005[ומקשה לו\u0006\u0005]\u0006 את \u0003כל הלין תיובתא\u0004 \u0005[הקושיות הללו\u0006\u0005]\u0006 להוכיח שדין זה קיים בכל מקום. \u0003הדר אמר ליה\u0004 \u0005[\u0006וחוזר ואומר לו\u0005]\u0006 שאולי נלמד מן הכתוב דבר הסותר את דבריו הראשונים, \u0003ליתן טעם כעיקר?\u0004","ומשיבים: \u0003בתר דשני ליה\u0004 \u0005[אחרי שתירץ לו\u0006\u0005]\u0006 רב דימי, וקיבל אביי את תירוצו שדין היתר מצטרף לאיסור אינו קיים בשאר איסורי תורה, \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 לרב דימי: \u0003דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003ליתן טעם כעיקר הוא דאתא\u0004 \u0005[שבא\u0006\u0005]\u0006 הכתוב, ואף בנזיר זה הוא טעם איסור המשרה?","\u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"משרת\"\u0004 בא ללמדנו \u0003ליתן טעם כעיקר,\u0004 כגון \u0003שאם שרה ענבים במים ויש בהם\u0004 במים \u0003טעם יין —\u0004 \u0003חייב\u0004 הנזיר אם שתה מהם. \u0003ומכאן אתה דן\u0004 (למד) בקל וחומר ל\u0003כל איסורין שבתורה\u0004 שכך דינם.","וכן דנים מנזיר לשאר איסורים: \u0003ומה נזיר שאין איסורו איסור עולם,\u0004 שהרי נדר הנזירות הוא כרגיל רק לזמן מסויים, \u0003ואין איסורו איסור הנאה,\u0004 שמותר לנזיר ליהנות מן היין הנאה שאינה אכילה ושתיה, \u0003ויש היתר לאיסורו\u0004 שהוא יכול להישאל לחכם ולבטל את הנדר, בכל זאת \u0003עשה בו טעם כעיקר,\u0004 \u0003כלאי הכרם\u0004 כגון שזרע זרעי תבואה עם זרע גפן \u0003שאיסורן\u0004 הוא \u0003איסור\u0004 ל\u0003עולם, ו\u0004כן גם \u0003איסורן\u0004 הוא \u0003איסור הנייה\u0004 (הנאה) ולא רק איסור אכילה, וחייבים לשרוף הכל, \u0003ו\u0004כן גם \u0003אין היתר לאיסורן —\u0004 \u0003אינו דין שיעשה בו טעם כעיקר?\u0004","\u0003והוא הדין לערלה בשתים\u0004 (בשני צדדים של חומרה שיש בה). שאף על פי שערלה אין איסורה איסור עולם כמו כלאי הכרם, שהרי כעבור שלוש שנים מותרים הפירות — מכל מקום איסור זה הוא איסור הנאה, וגם אין לו היתר.","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003ההוא מרבנן\u0004 \u0005[אחד מהחכמים\u0006\u0005]\u0006 לאביי: \u0003ר' אבהו כי קאמר\u0004 \u0005[כאשר אמר\u0006\u0005]\u0006 את דבריו בשם ר' יוחנן, שמ\"משרת\" למדים ענין היתר מצטרף לאיסור — \u0003ל\u0004שיטת \u0003ר' עקיבא\u0004 אמר. ומבררים: \u0003הי\u0004 \u0005[\u0006לאיזה\u0005]\u0006 מדברי \u0003ר' עקיבא\u0004 הוא מתכוון? \u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 לדברי \u0003ר' עקיבא דהכא\u0004 \u0005[של כאן\u0006\u0005],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנתנו\u0005],\u0006 \u0003ר' עקיבא אומר: אפילו שרה פיתו ביין ויש בו כדי לצרף כזית —\u0004 \u0003חייב,\u0004 יש לדחות: \u0003וממאי\u0004 \u0005[וממה,\u0006 מנין\u0005]\u0006 אתה יודע שמדובר כאן במקרה של היתר מצטרף לאיסור? \u0003דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 \u0003הוא\u0004 דווקא \u0003דאיכא\u0004 \u0005[כשיש\u0006\u0005]\u0006 \u0003כזית\u0004 מן היין \u0003בעינא\u0004 \u0005[בעינו\u0006\u0005],\u0006 בלא הפת, ונמצא נהנה מן היין כשיעור האסור לו!","\u0003וכי תימא\u0004 \u0005[ואם תאמר\u0006\u0005]:\u0006 אם כן \u0003מאי למימרא\u0004 \u0005[מה\u0006 בא לומר\u0005],\u0006 שאם יש שם כזית יין מה החידוש בזה שאסור? אפשר לומר שבא \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 מדברי ה\u0003תנא קמא\u0004 \u0005[הראשון\u0006\u0005]\u0006 ש\u0003אמר\u0004 שאינו חייב \u0003עד שישתה רביעית יין,\u0004 לכן בא ר' עקיבא לחדש שגם אם שתה כזית חייב עליו!","\u0003אלא,\u0004 יש לומר שהוא מתכוון לדברי \u0003ר' עקיבא דברייתא\u0004 \u0005[ש\u0006נאמרו בברייתא\u0005].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 \u0003ר' עקיבא אומר: נזיר ששרה פתו ביין, ואכל כזית מפת ומיין —\u0004 \u0003חייב.\u0004 וכאן ברורה משמעות הדברים שחייב משום שההיתר מצטרף לאיסור, שהרי לא אכל אלא כזית מן התערובת כולה.","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו\u0006\u0005]\u0006 של \u0003רב אויא לרב אשי: לר' עקיבא, דקא מוקים ליה להאי\u0004 \u0005[שמעמיד,\u0006 מסביר, את הכתוב הזה\u0005]\u0006 \u0003\"וכל משרת\" ל\u0004ענין \u0003היתר מצטרף לאיסור,\u0004 הדין האחר של \u0003ליתן טעם כעיקר מנא ליה\u0004 \u0005[מניין לו\u0006\u0005]?\u0006 ומשיבים: \u0003יליף\u0004 \u0005[\u0006הוא לומד\u0005]\u0006 את הדין הזה \u0003מבשר בחלב,\u0004 שאמרה תורה \"לא תבשל גדי בחלב אמו\" (שמות כג, יט). האם בשר וחלב שמתבשלים יחד \u0003לאו\u0004 \u0005[לא\u0006\u0005]\u0006 \u0003טעם בעלמא\u0004 \u0005[בלבד\u0006\u0005]\u0006 \u0003הוא,\u0004 שאחד נותן בשני \u0003ו\u0004בכל זאת \u0003אסור? הכא\u0004 \u0005[כאן\u0006\u0005],\u0006 בכל התורה כולה, \u0003נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003לא שנא\u0004 \u0005[שונה\u0006\u0005].\u0006","ומסבירים: \u0003ורבנן\u0004 \u0005[וחכמים\u0006\u0005],\u0006 החולקים על ר' עקיבא, ולמדים דין זה מ\"משרת\" ולא מבשר בחלב, הם סבורים כי \u0003מ\u0004דין \u0003בשר בחלב לא גמרינן\u0004 \u0005[אין אנו למדים\u0006\u0005]\u0006 משום ש\u0003חידוש הוא\u0004 וכלל בידינו שאין למדים מדבר שיש בו ענין יוצא דופן.","ושואלים: \u0003מאי חידושיה\u0004 \u0005[מהו חידושו\u0006\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 שהחידוש הוא \u0003דהאי לחודיה והאי לחודיה שרי ובהדי הדדי אסור\u0004 \u0005[ש\u0006בשר וחלב זה לחוד וזה לחוד מותר ויחד אסורים\u0005]\u0006 וזהו החידוש שבהלכה זו, אולם \u0003כלאים נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 זה דינם: \u0003האי לחודיה שרי והאי לחודיה שרי ובהדי הדדי אסור\u0004 \u0005[זה לעצמו מותר וזה לעצמו מותר וביחד הם אסורים\u0006\u0005]\u0006 ואם כן יש לנו דוגמאות כיוצא בכך בהלכות אחרות, ואין זה חידוש!","\u0003אלא\u0004 החידוש הוא אחר: \u0003דאי תרו ליה כולי יומא בחלבא\u0004 \u0005[שאם שורים אותו,\u0006 את הבשר, כל היום בחלב\u0005] —\u0006 \u0003שרי\u0004 \u0005[מותר\u0006\u0005]\u0006 \u0003ומבשיל ליה בשולי\u0004 \u0005[ו\u0006אולם אם מבשל אותו\u0005] —\u0006 \u0003אסור\u0004 וזהו החידוש, שלא עצם התערובת אסורה אלא בדרך בישול דווקא.","ושואלים: \u0003ור' עקיבא נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 הרי \u0003בשר בחלב חידוש הוא,\u0004 וכיצד אפשר ללמוד מכאן לכל התורה? \u0003אלא\u0004 יש לומר כי ר' עקיבא"],["\u0003יליף\u0004 \u0005[לומד\u0006\u0005]\u0006 \u0003מגיעולי גויים,\u0004 מאותם הכלים האסורים משום שבישלו בהם הגויים את תבשיליהם, \u0003דאמר רחמנא\u0004 \u0005[שאמרה תורה\u0006\u0005]:\u0006 \u0003\"כל דבר אשר יבא באש\u0004 תעבירו באש וטהר\u0003\"\u0004 (במדבר לא, כג) \u0003למימרא\u0004 \u0005[לומר\u0006\u0005]\u0006 לנו \u0003דאסירי\u0004 \u0005[שאסורים\u0006\u0005]\u0006 הם אותם כלים בלא שהגעילום קודם לכן. והרי \u0003גיעולי גויים לאו טעמא בעלמא\u0004 \u0005[\u0006האם לא טעם בלבד\u0005]\u0006 \u0003הוא\u0004 שקולט התבשיל מן הכלי שבישל בו הגוי \u0003ו\u0004בכל זאת \u0003אסור, הכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005],\u0006 בכל הלכות שבתורה, \u0003לא שנא\u0004 \u0005[שונה\u0006\u0005].\u0006 ולמדנו מכאן שטעם הדבר נחשב כעיקרו.","ועוד שאלו רב אחא את רב אשי: \u0003ולרבנן\u0004 \u0005[ולחכמים\u0006\u0005]\u0006 שלמדו דין זה מ\"משרת\" \u0003נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003תיפוק להו\u0004 \u0005[תצא,\u0006 תילמד, להם\u0005]\u0006 הלכה זו \u0003מגיעולי גויים\u0004 כמו לר' עקיבא? \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 רב אשי: \u0003התם\u0004 \u0005[שם\u0006\u0005]\u0006 \u0003חידוש הוא\u0004 ואין למדים מחידוש. ומדוע הוא חידוש — \u0003דהא\u0004 \u0005[שהרי\u0006\u0005]\u0006 \u0003בכל התורה כולה נותן טעם לפגם מותר,\u0004 שאם האיסור הנותן טעם בדבר אינו משביחו בכך אלא פוגם את טעמו — הריהו מותר מן התורה,","\u0003ו\u0004אילו \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003גיעולי גויים\u0004 נותן טעם לפגם \u0003אסור,\u0004 שהרי אם שהו הכלים זמן מסויים נפגם טעם האיסור שבהם, ובכל זאת אסור לבשל בהם. ואם כן אין ללמוד מכאן הלכה כללית.","ושואלים: \u0003ולר' עקיבא\u0004 הלומד מכאן לכל איסורים שבתורה \u0003נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 גם הוא צריך להודות ש\u0003חידוש הוא\u0004 שכן נותן טעם לפגם אסור! \u0003אמר רב הונא בר חייא: לא אסרה תורה\u0004 בענין זה של גיעולי גויים \u0003אלא לקדירה בת יומא\u0004 \u0005[יומה\u0006\u0005]\u0006 שבישלו בה באותו יום, \u0003דלאו\u0004 \u0005[ש\u0006במקרה זה לא\u0005]\u0006 \u0003נותן טעם לפגם הוא.\u0004","ומצד שני: \u0003ו\u0004לפי הסבר זה, \u0003רבנן\u0004 \u0005[חכמים\u0006\u0005],\u0006 מה הם אומרים על כך? — לדעתם \u0003קדירה בת יומא נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003אי אפשר\u0004 ש\u0003לא פגמה פורתא\u0004 \u0005[נפגם\u0006 הטעם במקצת\u0005]\u0006 ובכל זאת אסור לבשל בה, ואם כן יש באיסור זה של כלי גויים משום חידוש לגבי כל מקרה אחר של נתינת טעם, ולכן אין למדים ממנו.","ועוד \u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו\u0006\u0005]\u0006 של \u0003רב אויא לרב אשי: מדרבנן\u0004 \u0005[מדברי חכמים\u0006\u0005]\u0006 \u0003נשמע\u0004 ונלמד את שיטת \u0003ר' עקיבא. לאו אמרי רבנן\u0004 \u0005[האם לא אומרים חכמים\u0006\u0005]\u0006 כי \u0003האי\u0004 \u0005[זה\u0006\u0005]\u0006 הכתוב \u0003\"משרת\"\u0004 — בא לענין \u0003ליתן טעם כעיקר, ומכאן אתה דן לכל איסורין שבתורה.\u0004 אם כן, \u0003לר' עקיבא נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003דקא מוקים ליה להאי \"משרת\"\u0004 \u0005[שמעמיד\u0006 מסביר את \"משרת\" זה\u0005]\u0006 \u0003ל\u0004ענין \u0003היתר מצטרף לאיסור —\u0004 \u0003לימא\u0004 \u0005[נאמר\u0006\u0005]\u0006 ש\u0003מכאן אתה דן לכל איסורין שבתורה\u0004 ושלא כדברי ר' אבהו בשם ר' יוחנן שדין זה מיוחד רק לאיסור נזיר!","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 רב אשי: אפשר לדחות סברה זו, \u0003משום דהוי\u0004 \u0005[שהריהם\u0006\u0005]\u0006 \u0003נזיר וחטאת שני כתובין הבאין כאחד,\u0004 שבשניהם נתפרש דין זה של היתר מצטרף לאיסור. \u0003ו\u0004כלל הוא בידינו: ש\u0003כל שני כתובין הבאין כאחד\u0004 שבשניהם מפורש אותו דין, \u0003אין מלמדין\u0004 להלכות אחרות. ומסבירים מהם עניינם של אותם שני כתובים: \u0003נזיר —\u0004 \u0003הא דאמרן\u0004 \u0005[זה שאמרנו\u0006\u0005]\u0006 שהיתר מצטרף בו לאיסור מ\"משרת\". \u0003חטאת מאי\u0004 \u0005[מה\u0006\u0005]\u0006 \u0003היא?\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן שנינו בברייתא\u0005],\u0006 נאמר ביחס לקרבן חטאת: \u0003\"כל אשר יגע בבשרה יקדש\"\u0004 (ויקרא ו, כ) ונעשה דינו כחטאת, וצריך לנהוג בו כפי שנוהגים בחטאת. \u0003יכול\u0004 יהא דין זה \u0003אפילו שלא בלע\u0004 הנוגע מן החטאת אלא רק נגע בה — \u0003תלמוד לומר: \"בבשרה\",\u0004 ויכול היה לומר \"בה\", אלא לומר: \u0003עד שיבלע\u0004 מה ש\u0003בבשרה.\u0004","\u0003\"יקדש\"\u0004 — כוונתו: \u0003להיות כמוה, שאם פסולה היא\u0004 החטאת — \u0003יפסל\u0004 אף הוא, \u0003ואם כשרה\u0004 החטאת — \u0003תאכל\u0004 החתיכה האחרת \u0003כחמור שבה,\u0004 שכל החומרות שיש בחטאת צריכים להחמיר גם בדבר שנגע ובלע מן החטאת, או שנבלע בה.","\u0003ורבנן\u0004 \u0005[וחכמים\u0006\u0005]\u0006 החולקים על ר' עקיבא טוענים הם: אף לשיטתך, \u0003צריכי\u0004 \u0005[צריכים\u0006\u0005]\u0006 הדברים להיאמר גם בנזיר וגם בחטאת, כיון שאין הם יכולים להילמד זה מזה. ולכן אין פה שני כתובים הבאים כאחד. ומדוע אין הם למדים זה מזה? \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה\u0006\u0005]\u0006 דין זה רק \u0003גבי\u0004 \u0005[אצל\u0006\u0005]\u0006 \u0003חטאת —\u0004 \u0003הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]:\u0006 \u0003נזיר לא אתי מינה\u0004 \u0005[בא,\u0006 נלמד, ממנה\u0005]\u0006 \u0003משום שנזיר מ\u0004דיני \u0003קדשים לא ילפינן\u0004 \u0005[אין אנו למדים\u0006\u0005],\u0006 לפי שאיסור הנזיר אינו שייך לקדשים, אלא כשאר איסורים שבתורה ואפשר שזה דין מיוחד בקדשים.","ולהיפך, \u0003ואי כתב רחמנא גבי\u0004 \u0005[ואם היתה כותבת התורה\u0006 רק אצל\u0005]\u0006 \u0003נזיר, הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]:\u0006 \u0003מנזיר לא ילפינן\u0004 \u0005[אין אנו למדים\u0006\u0005]\u0006 \u0003משום דחמיר איסוריה\u0004 \u0005[שחמור איסורו\u0006\u0005],\u0006 ומדוע? ש\u0003אפילו חרצן\u0004 של גפן \u0003אסיר ליה\u0004 \u0005[אסור עליו\u0006\u0005]\u0006 אף שבדרך כלל אינו דבר שאוכלים אותו, \u0003הלכך לא אתיא מיניה\u0004 \u0005[על כן אין\u0006 חטאת יכולה לבוא, להילמד, ממנו\u0005]\u0006 ויש כאן איפוא שני דינים נבדלים, שאינם \"באים כאחד\", ואפשר ללמוד מהם הלכה כללית.","\u0003ור' עקיבא אמר\u0004 \u0005[\u0006יכול היה לומר\u0005]\u0006 \u0003לך\u0004 לדחות טענה זו: \u0003למאי צריכי\u0004 \u0005[למה\u0006 הם נצרכים\u0005]?\u0006 \u0003בשלמא אי כתב רחמנא\u0004 \u0005[נניח אם\u0006 היתה כותבת התורה\u0005]\u0006 דין זה רק לגבי \u0003חטאת\u0004 היה מובן, כי \u0003לא גמר\u0004 \u0005[נלמד\u0006\u0005]\u0006 דין \u0003נזיר מינה\u0004 \u0005[ממנה\u0006\u0005]\u0006 משום ש\u0003חולין מקדשים לא גמרינן\u0004 \u0005[אין אנו למדים\u0006\u0005]\u0006 וחטאת — קדשים היא. \u0003אלא לכתוב רחמנא\u0004 \u0005[שתכתוב התורה\u0006\u0005]\u0006 \u0003בנזיר\u0004 בלבד, \u0003ותיתי\u0004 \u0005[ותבוא,\u0006 תילמד\u0005]\u0006 \u0003חטאת מיניה\u0004 \u0005[ממנו\u0006\u0005],\u0006 \u0003דהא\u0004 \u0005[שהרי\u0006\u0005]\u0006 \u0003כל איסורין שבתורה קא גמרי\u0004 \u0005[למדים\u0006\u0005]\u0006 \u0003מנזיר,\u0004 ואם כן, בכל זאת יש כאן שני כתובים הבאים כאחד ואין מלמדים.","\u0003ורבנן אמרי לך\u0004 \u0005[וחכמים\u0006 יכולים לומר לך\u0005]:\u0006 מכל מקום לשיטתנו, דין \u0003חטאת\u0004 בא ללמדנו \u0003להיתר מצטרף לאיסור, ו\u0004אין למדים מכאן לכל התורה, כי \u0003חולין מקדשים לא גמרינן\u0004 \u0005[אין אנו למדים\u0006\u0005].\u0006","\u0003ו\u0004מה שנאמר \u0003\"משרת\"\u0004 — הוא \u0003ליתן טעם כעיקר,\u0004 ו\u0003מכאן אתה דן לכל איסורין שבתורה. ו\u0004אילו","\u0003ר' עקיבא,\u0004 לדעתו \u0003תרוייהו\u0004 \u0005[שניהם\u0006\u0005]\u0006 באים ללמד דבר אחד \u0003להיתר מצטרף לאיסור, והוו להו\u0004 \u0005[והרי הם\u0006\u0005]\u0006 אם כן \u0003שני כתובין הבאין כאחד, וכל שני כתובין הבאים כאחד אין מלמדין.\u0004","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]\u0006 \u0003רב אשי לרב כהנא: אלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר בפרשת נזיר: \u0003\"מכל אשר יעשה מגפן היין...\u0004 לא יאכל\u0003\"\u0004 (במדבר ו, ד) — \u0003לימד על איסורי נזיר שהן מצטרפין זה עם זה. ל\u0004דעת \u0003ר' עקיבא, השתא\u0004 \u0005[עכשיו\u0006\u0005]\u0006 \u0003יש לומר\u0004 לשיטתו ש\u0003היתר מצטרף לאיסור,\u0004 אם כן \u0003איסור לאיסור מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שהוא מצטרף?","\u0003אמר ליה\u0004 \u0005[לו\u0006\u0005]:\u0006 יש לחלק בין הדברים, כי אף לשיטת ר' עקיבא \u0003היתר לאיסור\u0004 מצטרף דווקא כשהוא אוכל אותם \u0003בבת אחת,\u0004 אבל \u0003איסור\u0004 מצטרף \u0003לאיסור —\u0004 \u0003אפילו בזה אחר זה,\u0004 שאם אכל כחצי זית מזה וחצי זית מזה, הרי הם מצטרפים.","ושואלים: \u0003ור' שמעון\u0004"]]};
